// Levítico — tradução dos originais (versificação: Nova Vulgata)
// Formato: {v: número, t: texto, n: nota (opcional)}
// =====================================================================

window.TEXTOS_SEED["levitico"][1] = [
{v:1,t:"O Senhor chamou Moisés e falou com ele desde a tenda do encontro, dizendo:"},
{v:2,t:"Fala aos filhos de Israel e dize a eles: Quando algum de vós apresentar uma oferta ao Senhor, apresentareis a vossa oferta de entre os animais, do gado graúdo ou do gado miúdo.",n:"O termo hebraico qorban, oferta, designa genericamente tudo o que se aproxima (qarab) do altar; conservei a palavra ampla, que abrange todos os sacrifícios do livro."},
{v:3,t:"Se a sua oferta for um holocausto de gado graúdo, apresentará um macho sem defeito; ele o apresentará à entrada da tenda do encontro, para que seja aceito diante do Senhor.",n:"Holocausto traduz olah, literalmente a que sobe, o sacrifício inteiramente queimado; sigo o termo consagrado pela tradição grega e latina."},
{v:4,t:"Porá a mão sobre a cabeça do holocausto, e este será aceito em seu favor, para fazer expiação por ele."},
{v:5,t:"Depois imolará o novilho diante do Senhor, e os filhos de Aarão, os sacerdotes, apresentarão o sangue e o derramarão ao redor sobre o altar que está à entrada da tenda do encontro."},
{v:6,t:"Então esfolará o holocausto e o cortará em pedaços."},
{v:7,t:"Os filhos do sacerdote Aarão porão fogo sobre o altar e arrumarão lenha sobre o fogo;"},
{v:8,t:"e os filhos de Aarão, os sacerdotes, disporão os pedaços, a cabeça e a gordura sobre a lenha que está no fogo, em cima do altar."},
{v:9,t:"As entranhas e as pernas, porém, ele as lavará com água; e o sacerdote queimará tudo sobre o altar: é um holocausto, oferta queimada de aroma agradável ao Senhor."},
{v:10,t:"Se a sua oferta for de gado miúdo, das ovelhas ou das cabras, para holocausto, apresentará um macho sem defeito."},
{v:11,t:"Ele o imolará ao lado norte do altar, diante do Senhor; e os filhos de Aarão, os sacerdotes, derramarão o sangue ao redor sobre o altar."},
{v:12,t:"Depois o cortará em pedaços, com a cabeça e a gordura, e o sacerdote os disporá sobre a lenha que está no fogo, em cima do altar."},
{v:13,t:"As entranhas e as pernas, porém, ele as lavará com água; e o sacerdote apresentará tudo e o queimará sobre o altar: é um holocausto, oferta queimada de aroma agradável ao Senhor."},
{v:14,t:"Se a sua oferta ao Senhor for um holocausto de aves, apresentará a sua oferta de rolas ou de pombinhos."},
{v:15,t:"O sacerdote a apresentará ao altar, destacará a cabeça com a unha e a queimará sobre o altar; e o seu sangue será espremido contra a parede do altar."},
{v:16,t:"Tirará o papo com as penas e o lançará junto ao altar, do lado do oriente, no lugar das cinzas."},
{v:17,t:"Depois a fenderá pelas asas, sem as separar; e o sacerdote a queimará sobre o altar, em cima da lenha que está no fogo: é um holocausto, oferta queimada de aroma agradável ao Senhor."}
];

window.TEXTOS_SEED["levitico"][2] = [
{v:1,t:"Quando alguém apresentar ao Senhor uma oferta de oblação, a sua oferta será de flor de farinha; derramará azeite sobre ela e porá incenso em cima,",n:"Oblação traduz minchah, a oferta vegetal de farinha; flor de farinha verte solet, a sêmola fina do trigo."},
{v:2,t:"e a levará aos filhos de Aarão, os sacerdotes. Dela tomará um punhado cheio da flor de farinha com o azeite e todo o incenso, e o sacerdote queimará esse memorial sobre o altar: oferta queimada de aroma agradável ao Senhor."},
{v:3,t:"O que restar da oblação será de Aarão e de seus filhos: é coisa santíssima dentre as ofertas queimadas ao Senhor."},
{v:4,t:"Quando apresentares uma oferta de oblação cozida no forno, será de flor de farinha: pães ázimos amassados com azeite e obreias ázimas untadas com azeite."},
{v:5,t:"Se a tua oferta for oblação preparada na chapa, será de flor de farinha amassada com azeite, sem fermento;"},
{v:6,t:"tu a partirás em pedaços e derramarás azeite sobre ela: é uma oblação."},
{v:7,t:"Se a tua oferta for oblação preparada na panela, será feita de flor de farinha com azeite."},
{v:8,t:"Levarás ao Senhor a oblação assim preparada; ela será entregue ao sacerdote, que a apresentará ao altar."},
{v:9,t:"O sacerdote separará da oblação o memorial e o queimará sobre o altar: oferta queimada de aroma agradável ao Senhor."},
{v:10,t:"O que restar da oblação será de Aarão e de seus filhos: é coisa santíssima dentre as ofertas queimadas ao Senhor."},
{v:11,t:"Nenhuma oblação que apresentardes ao Senhor será feita com fermento, porque nem fermento nem mel queimareis como oferta queimada ao Senhor."},
{v:12,t:"Podereis apresentar essas coisas ao Senhor como oferta de primícias, mas não subirão ao altar como aroma agradável."},
{v:13,t:"Toda oferta da tua oblação temperarás com sal; não deixarás faltar à tua oblação o sal da aliança do teu Deus: em todas as tuas ofertas apresentarás sal."},
{v:14,t:"Se apresentares ao Senhor uma oblação de primícias, apresentarás como oblação das tuas primícias espigas tostadas ao fogo e grãos triturados de trigo novo."},
{v:15,t:"Sobre ela porás azeite e colocarás incenso: é uma oblação."},
{v:16,t:"E o sacerdote queimará como memorial parte dos grãos triturados e do azeite, com todo o incenso: oferta queimada ao Senhor."}
];

window.TEXTOS_SEED["levitico"][3] = [
{v:1,t:"Se a sua oferta for um sacrifício de comunhão, e se a apresentar de gado graúdo, seja macho ou fêmea, apresentará diante do Senhor um animal sem defeito.",n:"Sacrifício de comunhão traduz zebach shelamim (na Nova Vulgata, hostia pacificorum): sacrifício cuja carne é repartida entre o altar, o sacerdote e o ofertante, selando a paz e a comunhão com Deus."},
{v:2,t:"Porá a mão sobre a cabeça da sua oferta e a imolará à entrada da tenda do encontro; e os filhos de Aarão, os sacerdotes, derramarão o sangue ao redor sobre o altar."},
{v:3,t:"Do sacrifício de comunhão apresentará, como oferta queimada ao Senhor, a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas,"},
{v:4,t:"os dois rins com a gordura que está sobre eles, junto aos lombos, e o lóbulo do fígado, que ele tirará com os rins."},
{v:5,t:"Os filhos de Aarão queimarão tudo isso sobre o altar, em cima do holocausto que está sobre a lenha posta no fogo: oferta queimada de aroma agradável ao Senhor."},
{v:6,t:"Se a sua oferta para sacrifício de comunhão ao Senhor for de gado miúdo, seja macho ou fêmea, apresentará um animal sem defeito."},
{v:7,t:"Se apresentar um cordeiro como sua oferta, ele o apresentará diante do Senhor;"},
{v:8,t:"porá a mão sobre a cabeça da sua oferta e a imolará diante da tenda do encontro; e os filhos de Aarão derramarão o sangue ao redor sobre o altar."},
{v:9,t:"Do sacrifício de comunhão apresentará, como oferta queimada ao Senhor, a sua gordura: a cauda inteira, que cortará rente ao espinhaço, a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas,"},
{v:10,t:"os dois rins com a gordura que está sobre eles, junto aos lombos, e o lóbulo do fígado, que ele tirará com os rins."},
{v:11,t:"E o sacerdote queimará isso sobre o altar: é alimento de oferta queimada ao Senhor."},
{v:12,t:"Se a sua oferta for uma cabra, ele a apresentará diante do Senhor;"},
{v:13,t:"porá a mão sobre a cabeça dela e a imolará diante da tenda do encontro; e os filhos de Aarão derramarão o sangue ao redor sobre o altar."},
{v:14,t:"Dela apresentará a sua oferta, como oferta queimada ao Senhor: a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas,"},
{v:15,t:"os dois rins com a gordura que está sobre eles, junto aos lombos, e o lóbulo do fígado, que ele tirará com os rins."},
{v:16,t:"E o sacerdote queimará isso sobre o altar: é alimento de oferta queimada, de aroma agradável. Toda a gordura pertence ao Senhor."},
{v:17,t:"É preceito perpétuo pelas vossas gerações, em todas as vossas moradas: não comereis gordura alguma nem sangue algum."}
];

window.TEXTOS_SEED["levitico"][4] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala aos filhos de Israel: Quando alguém pecar por inadvertência contra qualquer dos mandamentos do Senhor, fazendo algo que não se deve fazer,",n:"Por inadvertência traduz bishgagah: o pecado cometido sem plena consciência ou intenção, único contemplado por estes sacrifícios."},
{v:3,t:"se for o sacerdote ungido que pecar, tornando o povo culpado, apresentará ao Senhor, pelo pecado que cometeu, um novilho sem defeito, como sacrifício pelo pecado."},
{v:4,t:"Levará o novilho à entrada da tenda do encontro, diante do Senhor, porá a mão sobre a cabeça do novilho e o imolará diante do Senhor."},
{v:5,t:"O sacerdote ungido tomará do sangue do novilho e o levará à tenda do encontro;"},
{v:6,t:"molhará o dedo no sangue e o aspergirá sete vezes diante do Senhor, defronte do véu do santuário."},
{v:7,t:"Depois o sacerdote porá do sangue sobre os chifres do altar do incenso aromático, que está diante do Senhor, na tenda do encontro; e derramará todo o resto do sangue do novilho na base do altar dos holocaustos, que está à entrada da tenda do encontro."},
{v:8,t:"Tirará toda a gordura do novilho do sacrifício pelo pecado: a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas,"},
{v:9,t:"os dois rins com a gordura que está sobre eles, junto aos lombos, e o lóbulo do fígado, que ele tirará com os rins,"},
{v:10,t:"assim como se tira do novilho do sacrifício de comunhão; e o sacerdote os queimará sobre o altar dos holocaustos."},
{v:11,t:"Mas o couro do novilho e toda a sua carne, com a cabeça, as pernas, as entranhas e os excrementos,"},
{v:12,t:"o novilho inteiro, ele o levará para fora do acampamento, a um lugar puro, onde se despejam as cinzas, e o queimará sobre lenha, no fogo: será queimado no lugar onde se despejam as cinzas."},
{v:13,t:"Se toda a comunidade de Israel pecar por inadvertência, sem que a assembleia se dê conta, e fizerem qualquer coisa que os mandamentos do Senhor proíbem, tornando-se culpados,"},
{v:14,t:"quando vier a ser conhecido o pecado que cometeram, a assembleia apresentará um novilho como sacrifício pelo pecado e o levará diante da tenda do encontro."},
{v:15,t:"Os anciãos da comunidade porão as mãos sobre a cabeça do novilho diante do Senhor, e o novilho será imolado diante do Senhor."},
{v:16,t:"O sacerdote ungido levará do sangue do novilho à tenda do encontro;"},
{v:17,t:"molhará o dedo no sangue e o aspergirá sete vezes diante do Senhor, defronte do véu."},
{v:18,t:"Porá do sangue sobre os chifres do altar que está diante do Senhor, na tenda do encontro; e derramará todo o resto do sangue na base do altar dos holocaustos, que está à entrada da tenda do encontro."},
{v:19,t:"Tirará dele toda a gordura e a queimará sobre o altar."},
{v:20,t:"Fará com este novilho como fez com o novilho do sacrifício pelo pecado; assim fará com ele. O sacerdote fará expiação por eles, e lhes será perdoado."},
{v:21,t:"Depois levará o novilho para fora do acampamento e o queimará como queimou o primeiro novilho: é o sacrifício pelo pecado da assembleia."},
{v:22,t:"Quando um chefe pecar, fazendo por inadvertência algo que os mandamentos do Senhor seu Deus proíbem, tornando-se culpado,"},
{v:23,t:"logo que lhe for dado conhecer o pecado que cometeu, trará como sua oferta um bode sem defeito."},
{v:24,t:"Porá a mão sobre a cabeça do bode e o imolará no lugar onde se imola o holocausto, diante do Senhor: é um sacrifício pelo pecado."},
{v:25,t:"O sacerdote tomará com o dedo do sangue do sacrifício pelo pecado e o porá sobre os chifres do altar dos holocaustos; e derramará o resto do sangue na base do altar dos holocaustos."},
{v:26,t:"Queimará toda a gordura sobre o altar, como a gordura do sacrifício de comunhão. Assim o sacerdote fará expiação por ele, pelo seu pecado, e lhe será perdoado."},
{v:27,t:"Se alguém do povo da terra pecar por inadvertência, fazendo algo que os mandamentos do Senhor proíbem, tornando-se culpado,"},
{v:28,t:"logo que lhe for dado conhecer o pecado que cometeu, trará como sua oferta, pelo pecado que cometeu, uma cabra sem defeito."},
{v:29,t:"Porá a mão sobre a cabeça do sacrifício pelo pecado e o imolará no lugar do holocausto."},
{v:30,t:"O sacerdote tomará com o dedo do sangue dela e o porá sobre os chifres do altar dos holocaustos; e derramará todo o resto do sangue na base do altar."},
{v:31,t:"Tirará toda a gordura, como se tira a gordura do sacrifício de comunhão, e o sacerdote a queimará sobre o altar, em aroma agradável ao Senhor. Assim o sacerdote fará expiação por ele, e lhe será perdoado."},
{v:32,t:"Se trouxer uma ovelha como oferta pelo pecado, trará uma fêmea sem defeito."},
{v:33,t:"Porá a mão sobre a cabeça do sacrifício pelo pecado e a imolará, como sacrifício pelo pecado, no lugar onde se imola o holocausto."},
{v:34,t:"O sacerdote tomará com o dedo do sangue do sacrifício pelo pecado e o porá sobre os chifres do altar dos holocaustos; e derramará todo o resto do sangue na base do altar."},
{v:35,t:"Tirará toda a gordura, como se tira a gordura do cordeiro do sacrifício de comunhão, e o sacerdote a queimará sobre o altar, em cima das ofertas queimadas ao Senhor. Assim o sacerdote fará expiação por ele, pelo pecado que cometeu, e lhe será perdoado."}
];

window.TEXTOS_SEED["levitico"][5] = [
{v:1,t:"Se alguém pecar por ter ouvido a fórmula de adjuração e, sendo testemunha do que viu ou soube, não o declarar, carregará a sua iniquidade."},
{v:2,t:"Ou se alguém tocar qualquer coisa impura, seja o cadáver de uma fera impura, seja o cadáver de um animal doméstico impuro, seja o cadáver de um réptil impuro, ainda que sem se dar conta, ficará impuro e culpado."},
{v:3,t:"Ou se tocar alguma impureza humana, qualquer impureza pela qual alguém se torna impuro, sem se dar conta, quando o souber, será culpado."},
{v:4,t:"Ou se alguém, falando irrefletidamente com os lábios, jurar fazer mal ou fazer bem, em tudo o que o homem pode jurar irrefletidamente, sem se dar conta, quando o souber, será culpado de uma dessas coisas."},
{v:5,t:"Quando alguém, pois, for culpado de uma dessas coisas, confessará aquilo em que pecou"},
{v:6,t:"e trará ao Senhor, como reparação pelo pecado que cometeu, uma fêmea de gado miúdo, ovelha ou cabra, como sacrifício pelo pecado; e o sacerdote fará expiação por ele, pelo seu pecado."},
{v:7,t:"Se não tiver recursos para um animal do rebanho, trará ao Senhor, como reparação pelo pecado que cometeu, duas rolas ou dois pombinhos: um para sacrifício pelo pecado e outro para holocausto."},
{v:8,t:"Ele os trará ao sacerdote, que apresentará primeiro o que é para o sacrifício pelo pecado: destacará a cabeça junto à nuca, sem a separar,"},
{v:9,t:"e aspergirá do sangue do sacrifício pelo pecado a parede do altar; o resto do sangue será espremido na base do altar: é um sacrifício pelo pecado."},
{v:10,t:"Do segundo fará um holocausto, segundo o rito. Assim o sacerdote fará expiação por ele, pelo pecado que cometeu, e lhe será perdoado."},
{v:11,t:"Se não tiver recursos nem para duas rolas ou dois pombinhos, trará como oferta, pelo pecado que cometeu, a décima parte de um efá de flor de farinha, como sacrifício pelo pecado; não porá sobre ela azeite nem colocará incenso, porque é um sacrifício pelo pecado.",n:"O efá era medida de secos em torno de vinte e dois litros; a décima parte, cerca de dois litros de farinha."},
{v:12,t:"Ele a trará ao sacerdote; o sacerdote tomará dela um punhado cheio, como memorial, e o queimará sobre o altar, em cima das ofertas queimadas ao Senhor: é um sacrifício pelo pecado."},
{v:13,t:"Assim o sacerdote fará expiação por ele, pelo pecado que cometeu em qualquer dessas coisas, e lhe será perdoado. O restante pertencerá ao sacerdote, como na oblação."},
{v:14,t:"O Senhor falou a Moisés, dizendo:"},
{v:15,t:"Se alguém cometer uma infidelidade, pecando por inadvertência contra as coisas consagradas ao Senhor, trará ao Senhor, como sua reparação, um carneiro sem defeito do rebanho, avaliado em siclos de prata, segundo o siclo do santuário, como sacrifício de reparação.",n:"Sacrifício de reparação traduz asham (na Nova Vulgata, sacrificium pro delicto): distingue-se do sacrifício pelo pecado por acompanhar a restituição do dano, acrescida de um quinto."},
{v:16,t:"Restituirá o que subtraiu do santuário, acrescentará um quinto e o dará ao sacerdote; o sacerdote fará expiação por ele com o carneiro do sacrifício de reparação, e lhe será perdoado."},
{v:17,t:"Se alguém pecar, fazendo, sem o saber, algo que os mandamentos do Senhor proíbem, será culpado e carregará a sua iniquidade."},
{v:18,t:"Trará ao sacerdote um carneiro sem defeito do rebanho, conforme a avaliação, como sacrifício de reparação; o sacerdote fará expiação por ele, pela inadvertência que cometeu sem saber, e lhe será perdoado:"},
{v:19,t:"é um sacrifício de reparação; ele era de fato culpado diante do Senhor."},
{v:20,t:"O Senhor falou a Moisés, dizendo:"},
{v:21,t:"Se alguém pecar e cometer uma infidelidade contra o Senhor, negando ao seu próximo um depósito, um penhor confiado às suas mãos ou coisa roubada, ou se extorquir o seu próximo,"},
{v:22,t:"ou se achar um objeto perdido e o negar, jurando falso a respeito de qualquer das coisas em que o homem costuma pecar,"},
{v:23,t:"quando assim pecar e se tornar culpado, restituirá o que roubou, ou o que extorquiu, ou o depósito que lhe foi confiado, ou o objeto perdido que achou,"},
{v:24,t:"ou qualquer coisa sobre a qual jurou falso; restituirá tudo por inteiro, acrescentará um quinto e o dará a quem pertence, no dia do seu sacrifício de reparação."},
{v:25,t:"E trará ao Senhor, como sua reparação, um carneiro sem defeito do rebanho, conforme a avaliação, para o sacrifício de reparação; ele o entregará ao sacerdote,"},
{v:26,t:"e o sacerdote fará expiação por ele diante do Senhor, e lhe será perdoada qualquer das coisas que fez e pelas quais se tornou culpado.",n:"Na versificação da Nova Vulgata, que segue o texto hebraico, o capítulo 5 termina aqui; nas Bíblias que seguem a divisão grega, estes versículos 20 a 26 correspondem a 6, 1 a 7."}
];

window.TEXTOS_SEED["levitico"][6] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Dá esta ordem a Aarão e a seus filhos: Esta é a lei do holocausto. O holocausto ficará sobre o braseiro do altar toda a noite, até de manhã, e o fogo do altar será mantido aceso nele."},
{v:3,t:"O sacerdote vestirá a sua túnica de linho e vestirá sobre o corpo os calções de linho; tirará as cinzas a que o fogo reduziu o holocausto sobre o altar e as porá ao lado do altar."},
{v:4,t:"Depois despirá as suas vestes, vestirá outras e levará as cinzas para fora do acampamento, a um lugar puro."},
{v:5,t:"O fogo será mantido aceso sobre o altar, sem se apagar; o sacerdote acenderá lenha sobre ele a cada manhã, disporá em cima o holocausto e sobre ele queimará as gorduras dos sacrifícios de comunhão."},
{v:6,t:"É o fogo perpétuo que arderá sobre o altar, sem jamais se apagar."},
{v:7,t:"Esta é a lei da oblação: os filhos de Aarão a apresentarão diante do Senhor, defronte do altar."},
{v:8,t:"Um deles separará um punhado da flor de farinha da oblação, com o seu azeite e todo o incenso que está sobre a oblação, e o queimará sobre o altar, como aroma agradável, memorial para o Senhor."},
{v:9,t:"O que dela restar, Aarão e seus filhos o comerão; será comido sem fermento, em lugar santo: no átrio da tenda do encontro o comerão."},
{v:10,t:"Não será cozido com fermento. É a porção que lhes dei das minhas ofertas queimadas: é coisa santíssima, como o sacrifício pelo pecado e o sacrifício de reparação."},
{v:11,t:"Todo varão dentre os filhos de Aarão poderá comer dela. É preceito perpétuo pelas vossas gerações, acerca das ofertas queimadas ao Senhor: tudo o que as tocar ficará santo."},
{v:12,t:"O Senhor falou a Moisés, dizendo:"},
{v:13,t:"Esta é a oferta que Aarão e seus filhos apresentarão ao Senhor no dia da sua unção: a décima parte de um efá de flor de farinha, como oblação perpétua, metade pela manhã e metade à tarde."},
{v:14,t:"Será preparada na chapa, com azeite; tu a trarás bem embebida e apresentarás os pedaços da oblação partida, em aroma agradável ao Senhor."},
{v:15,t:"O sacerdote que, dentre os seus filhos, for ungido em seu lugar fará o mesmo. É preceito perpétuo: será queimada inteiramente para o Senhor."},
{v:16,t:"Toda oblação de sacerdote será oferta total: não se comerá dela."},
{v:17,t:"O Senhor falou a Moisés, dizendo:"},
{v:18,t:"Fala a Aarão e a seus filhos: Esta é a lei do sacrifício pelo pecado. No lugar onde se imola o holocausto será imolado o sacrifício pelo pecado, diante do Senhor: é coisa santíssima."},
{v:19,t:"O sacerdote que o oferecer o comerá; será comido em lugar santo, no átrio da tenda do encontro."},
{v:20,t:"Tudo o que tocar a sua carne ficará santo; se o seu sangue respingar sobre alguma veste, lavarás em lugar santo a parte respingada."},
{v:21,t:"O vaso de barro em que for cozido será quebrado; se for cozido em vaso de bronze, este será esfregado e lavado com água."},
{v:22,t:"Todo varão dentre os sacerdotes poderá comer dele: é coisa santíssima."},
{v:23,t:"Mas nenhum sacrifício pelo pecado, de cujo sangue se leva à tenda do encontro para fazer expiação no santuário, será comido: será queimado no fogo."}
];

window.TEXTOS_SEED["levitico"][7] = [
{v:1,t:"Esta é a lei do sacrifício de reparação: é coisa santíssima."},
{v:2,t:"No lugar onde se imola o holocausto será imolado o sacrifício de reparação, e o seu sangue será derramado ao redor sobre o altar."},
{v:3,t:"Dele se apresentará toda a gordura: a cauda, a gordura que cobre as entranhas,"},
{v:4,t:"os dois rins com a gordura que está sobre eles, junto aos lombos, e o lóbulo do fígado, que será tirado com os rins."},
{v:5,t:"O sacerdote os queimará sobre o altar, como oferta queimada ao Senhor: é um sacrifício de reparação."},
{v:6,t:"Todo varão dentre os sacerdotes poderá comer dele; será comido em lugar santo: é coisa santíssima."},
{v:7,t:"Como o sacrifício pelo pecado, assim é o sacrifício de reparação: uma só lei há para ambos. Pertencerá ao sacerdote que com ele fizer a expiação."},
{v:8,t:"O sacerdote que oferecer o holocausto de alguém terá para si o couro do holocausto que ofereceu."},
{v:9,t:"Toda oblação cozida no forno e toda a que for preparada na panela ou na chapa pertencerá ao sacerdote que a oferecer."},
{v:10,t:"Mas toda oblação amassada com azeite, ou seca, pertencerá a todos os filhos de Aarão, em partes iguais."},
{v:11,t:"Esta é a lei do sacrifício de comunhão que se apresenta ao Senhor."},
{v:12,t:"Se alguém o oferecer em ação de graças, oferecerá, com o sacrifício de ação de graças, pães ázimos amassados com azeite, obreias ázimas untadas com azeite e flor de farinha embebida, em bolos amassados com azeite."},
{v:13,t:"Com bolos de pão fermentado apresentará a sua oferta, junto com o seu sacrifício de comunhão em ação de graças."},
{v:14,t:"De cada uma dessas ofertas apresentará um pão como oferta elevada ao Senhor: pertencerá ao sacerdote que derramar o sangue do sacrifício de comunhão."},
{v:15,t:"A carne do sacrifício de comunhão em ação de graças será comida no dia em que for oferecida: nada se deixará dela até de manhã."},
{v:16,t:"Se o sacrifício for oferecido por voto ou como oferta espontânea, será comido no dia em que for oferecido, e o que dele sobrar será comido no dia seguinte;"},
{v:17,t:"mas o que ainda sobrar da carne do sacrifício ao terceiro dia será queimado no fogo."},
{v:18,t:"Se alguém comer da carne do seu sacrifício de comunhão ao terceiro dia, o sacrifício não será aceito nem contará em favor de quem o ofereceu: será coisa abominável, e quem dela comer carregará a sua iniquidade."},
{v:19,t:"A carne que tocar qualquer coisa impura não será comida: será queimada no fogo. Quanto à carne do sacrifício, todo aquele que estiver puro poderá comer dela;"},
{v:20,t:"mas quem, estando impuro, comer da carne do sacrifício de comunhão que pertence ao Senhor, esse será eliminado do seu povo."},
{v:21,t:"E quem tocar qualquer coisa impura, impureza humana, animal impuro ou qualquer coisa abominável e impura, e comer da carne do sacrifício de comunhão que pertence ao Senhor, esse será eliminado do seu povo."},
{v:22,t:"O Senhor falou a Moisés, dizendo:"},
{v:23,t:"Fala aos filhos de Israel: Não comereis gordura alguma de boi, de ovelha ou de cabra."},
{v:24,t:"A gordura de animal morto e a gordura de animal dilacerado poderão servir para qualquer uso, mas de modo algum a comereis."},
{v:25,t:"Quem comer gordura de animal que se apresenta ao Senhor como oferta queimada será eliminado do seu povo."},
{v:26,t:"Em nenhuma das vossas moradas comereis sangue algum, nem de ave nem de animal."},
{v:27,t:"Quem comer qualquer sangue será eliminado do seu povo."},
{v:28,t:"O Senhor falou a Moisés, dizendo:"},
{v:29,t:"Fala aos filhos de Israel: Quem apresentar ao Senhor o seu sacrifício de comunhão trará ao Senhor a sua oferta, tirada do seu sacrifício de comunhão."},
{v:30,t:"As suas próprias mãos trarão as ofertas queimadas ao Senhor: trará a gordura com o peito, e moverá o peito com um gesto para a frente e para trás, como oferenda movida diante do Senhor."},
{v:31,t:"O sacerdote queimará a gordura sobre o altar, mas o peito pertencerá a Aarão e a seus filhos."},
{v:32,t:"Dareis também a coxa direita dos vossos sacrifícios de comunhão ao sacerdote, como oferta elevada."},
{v:33,t:"Aquele dentre os filhos de Aarão que oferecer o sangue e a gordura dos sacrifícios de comunhão terá a coxa direita como sua porção."},
{v:34,t:"Porque o peito da oferenda movida e a coxa da oferta elevada eu os tomei dos filhos de Israel, dos seus sacrifícios de comunhão, e os dei ao sacerdote Aarão e a seus filhos, como direito perpétuo da parte dos filhos de Israel."},
{v:35,t:"Esta é a porção de Aarão e a porção de seus filhos nas ofertas queimadas ao Senhor, desde o dia em que foram apresentados para exercer o sacerdócio do Senhor;"},
{v:36,t:"é o que o Senhor ordenou que lhes fosse dado pelos filhos de Israel, desde o dia da sua unção: preceito perpétuo pelas suas gerações."},
{v:37,t:"Esta é a lei do holocausto, da oblação, do sacrifício pelo pecado, do sacrifício de reparação, do sacrifício de investidura e do sacrifício de comunhão,"},
{v:38,t:"que o Senhor prescreveu a Moisés no monte Sinai, no dia em que ordenou aos filhos de Israel que apresentassem as suas ofertas ao Senhor, no deserto do Sinai."}
];

window.TEXTOS_SEED["levitico"][8] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Toma Aarão e, com ele, seus filhos, as vestes, o óleo da unção, o novilho do sacrifício pelo pecado, os dois carneiros e o cesto dos ázimos,"},
{v:3,t:"e reúne toda a comunidade à entrada da tenda do encontro."},
{v:4,t:"Moisés fez como o Senhor lhe ordenara, e a comunidade se reuniu à entrada da tenda do encontro."},
{v:5,t:"E Moisés disse à comunidade: Isto é o que o Senhor ordenou que se fizesse."},
{v:6,t:"Moisés fez aproximarem-se Aarão e seus filhos e os lavou com água."},
{v:7,t:"Vestiu em Aarão a túnica, cingiu-o com o cíngulo, revestiu-o do manto, pôs sobre ele o efod, cingiu-o com o cinto do efod e com ele o ajustou."},
{v:8,t:"Colocou sobre ele o peitoral e no peitoral pôs o Urim e o Tumim.",n:"Urim e Tumim: objetos guardados no peitoral do sumo sacerdote para consultar a vontade de Deus; o sentido exato dos nomes é incerto, e por isso conservei a transliteração tradicional."},
{v:9,t:"Pôs o turbante sobre a sua cabeça e, no turbante, na parte da frente, colocou a lâmina de ouro, o diadema sagrado, como o Senhor ordenara a Moisés."},
{v:10,t:"Depois Moisés tomou o óleo da unção, ungiu o tabernáculo e tudo o que nele havia, e os consagrou."},
{v:11,t:"Aspergiu com ele o altar sete vezes, ungiu o altar e todos os seus utensílios, a bacia e a sua base, para os consagrar."},
{v:12,t:"Derramou do óleo da unção sobre a cabeça de Aarão e o ungiu, para o consagrar."},
{v:13,t:"Moisés fez aproximarem-se os filhos de Aarão, vestiu neles as túnicas, cingiu-os com os cíngulos e prendeu-lhes as mitras, como o Senhor ordenara a Moisés."},
{v:14,t:"Fez então trazer o novilho do sacrifício pelo pecado, e Aarão e seus filhos puseram as mãos sobre a cabeça do novilho."},
{v:15,t:"Moisés o imolou, tomou o sangue e com o dedo o pôs sobre os chifres do altar, ao redor, e purificou o altar; derramou o resto do sangue na base do altar e o consagrou, fazendo por ele expiação."},
{v:16,t:"Tomou toda a gordura que estava sobre as entranhas, o lóbulo do fígado e os dois rins com a sua gordura, e queimou tudo sobre o altar."},
{v:17,t:"Mas o novilho, com o couro, a carne e os excrementos, ele o queimou no fogo fora do acampamento, como o Senhor ordenara a Moisés."},
{v:18,t:"Depois fez trazer o carneiro do holocausto, e Aarão e seus filhos puseram as mãos sobre a cabeça do carneiro."},
{v:19,t:"Moisés o imolou e derramou o sangue ao redor sobre o altar."},
{v:20,t:"Cortou o carneiro em pedaços e queimou a cabeça, os pedaços e a gordura."},
{v:21,t:"Lavou com água as entranhas e as pernas, e queimou o carneiro inteiro sobre o altar: era um holocausto de aroma agradável, oferta queimada ao Senhor, como o Senhor ordenara a Moisés."},
{v:22,t:"Fez então trazer o segundo carneiro, o carneiro da investidura, e Aarão e seus filhos puseram as mãos sobre a cabeça do carneiro."},
{v:23,t:"Moisés o imolou, tomou do seu sangue e o pôs sobre o lóbulo da orelha direita de Aarão, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito."},
{v:24,t:"Fez aproximarem-se os filhos de Aarão, pôs do sangue sobre o lóbulo da orelha direita deles, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito, e derramou o resto do sangue ao redor sobre o altar."},
{v:25,t:"Tomou a gordura, a cauda, toda a gordura que estava sobre as entranhas, o lóbulo do fígado, os dois rins com a sua gordura e a coxa direita."},
{v:26,t:"Do cesto dos ázimos, que estava diante do Senhor, tomou um pão ázimo, um bolo de pão com azeite e uma obreia, e os pôs sobre as gorduras e sobre a coxa direita."},
{v:27,t:"Pôs tudo isso nas mãos de Aarão e nas mãos de seus filhos, e eles moveram tudo com um gesto para a frente e para trás, como oferenda movida diante do Senhor."},
{v:28,t:"Depois Moisés os tomou das suas mãos e os queimou sobre o altar, em cima do holocausto: era o sacrifício de investidura, de aroma agradável, oferta queimada ao Senhor."},
{v:29,t:"Moisés tomou o peito e o moveu com um gesto para a frente e para trás, como oferenda movida diante do Senhor; do carneiro da investidura, esta foi a porção de Moisés, como o Senhor ordenara a Moisés."},
{v:30,t:"Moisés tomou do óleo da unção e do sangue que estava sobre o altar, e os aspergiu sobre Aarão e as suas vestes, e igualmente sobre seus filhos e as vestes de seus filhos; e consagrou Aarão e as suas vestes, e com ele seus filhos e as vestes de seus filhos."},
{v:31,t:"Moisés disse a Aarão e a seus filhos: Cozinhai a carne à entrada da tenda do encontro; ali a comereis, com o pão que está no cesto da investidura, conforme me foi ordenado: Aarão e seus filhos a comerão."},
{v:32,t:"O que sobrar da carne e do pão, queimareis no fogo."},
{v:33,t:"Durante sete dias não saireis da entrada da tenda do encontro, até que se completem os dias da vossa investidura, porque a vossa investidura durará sete dias."},
{v:34,t:"Como se fez hoje, assim o Senhor ordenou que se faça, para fazer expiação por vós."},
{v:35,t:"Ficareis, pois, à entrada da tenda do encontro dia e noite, durante sete dias, e guardareis a observância do Senhor, para que não morrais: assim me foi ordenado."},
{v:36,t:"E Aarão e seus filhos fizeram todas as coisas que o Senhor ordenara por meio de Moisés."}
];

window.TEXTOS_SEED["levitico"][9] = [
{v:1,t:"No oitavo dia, Moisés chamou Aarão e seus filhos, e os anciãos de Israel,"},
{v:2,t:"e disse a Aarão: Toma um bezerro para sacrifício pelo pecado e um carneiro para holocausto, ambos sem defeito, e apresenta-os diante do Senhor."},
{v:3,t:"E aos filhos de Israel falarás assim: Tomai um bode para sacrifício pelo pecado, um bezerro e um cordeiro, ambos de um ano e sem defeito, para holocausto,"},
{v:4,t:"um boi e um carneiro para sacrifício de comunhão, para os imolar diante do Senhor, e uma oblação amassada com azeite; porque hoje o Senhor aparecerá a vós."},
{v:5,t:"Levaram, pois, diante da tenda do encontro o que Moisés ordenara, e toda a comunidade se aproximou e ficou de pé diante do Senhor."},
{v:6,t:"E Moisés disse: Isto é o que o Senhor vos ordenou; fazei-o, e a glória do Senhor aparecerá a vós."},
{v:7,t:"Depois Moisés disse a Aarão: Aproxima-te do altar, faze o teu sacrifício pelo pecado e o teu holocausto, e faze expiação por ti e pelo povo; faze também a oferta do povo e faze expiação por ele, como o Senhor ordenou."},
{v:8,t:"Aarão aproximou-se do altar e imolou o bezerro do sacrifício pelo seu pecado."},
{v:9,t:"Os filhos de Aarão apresentaram-lhe o sangue; ele molhou o dedo no sangue, pôs do sangue sobre os chifres do altar e derramou o resto na base do altar."},
{v:10,t:"A gordura, os rins e o lóbulo do fígado do sacrifício pelo pecado, ele os queimou sobre o altar, como o Senhor ordenara a Moisés;"},
{v:11,t:"mas a carne e o couro, ele os queimou no fogo fora do acampamento."},
{v:12,t:"Depois imolou o holocausto; os filhos de Aarão entregaram-lhe o sangue, e ele o derramou ao redor sobre o altar."},
{v:13,t:"Entregaram-lhe o holocausto em pedaços, com a cabeça, e ele os queimou sobre o altar."},
{v:14,t:"Lavou as entranhas e as pernas, e as queimou sobre o holocausto, no altar."},
{v:15,t:"Fez então aproximar a oferta do povo: tomou o bode do sacrifício pelo pecado do povo, imolou-o e o ofereceu pelo pecado, como fizera com o primeiro."},
{v:16,t:"Apresentou o holocausto e o fez segundo o rito."},
{v:17,t:"Apresentou a oblação, tomou dela um punhado cheio e o queimou sobre o altar, além do holocausto da manhã."},
{v:18,t:"Imolou também o boi e o carneiro do sacrifício de comunhão do povo; os filhos de Aarão entregaram-lhe o sangue, e ele o derramou ao redor sobre o altar."},
{v:19,t:"As gorduras do boi e do carneiro, a cauda, a gordura que cobre as entranhas, os rins e o lóbulo do fígado,"},
{v:20,t:"puseram essas gorduras sobre os peitos, e ele queimou as gorduras sobre o altar."},
{v:21,t:"Quanto aos peitos e à coxa direita, Aarão os moveu com um gesto para a frente e para trás, como oferenda movida diante do Senhor, conforme Moisés ordenara."},
{v:22,t:"Depois Aarão levantou as mãos para o povo e o abençoou; e, tendo terminado o sacrifício pelo pecado, o holocausto e o sacrifício de comunhão, desceu do altar."},
{v:23,t:"Moisés e Aarão entraram na tenda do encontro; ao sair, abençoaram o povo, e a glória do Senhor apareceu a todo o povo."},
{v:24,t:"Um fogo saiu de diante do Senhor e consumiu, sobre o altar, o holocausto e as gorduras. Vendo isto, todo o povo soltou gritos de júbilo e caiu com o rosto por terra."}
];

window.TEXTOS_SEED["levitico"][10] = [
{v:1,t:"Nadab e Abiú, filhos de Aarão, tomaram cada um o seu incensário, puseram neles fogo, colocaram incenso por cima e apresentaram diante do Senhor um fogo estranho, que ele não lhes havia ordenado.",n:"Fogo estranho traduz esh zarah: brasas não tomadas do altar, isto é, um culto realizado fora do que Deus prescrevera."},
{v:2,t:"Então saiu um fogo de diante do Senhor e os devorou, e morreram diante do Senhor."},
{v:3,t:"E Moisés disse a Aarão: É o que o Senhor declarou, dizendo: Serei santificado naqueles que se aproximam de mim, e diante de todo o povo serei glorificado. E Aarão ficou em silêncio."},
{v:4,t:"Moisés chamou Misael e Elisafã, filhos de Uziel, tio de Aarão, e disse a eles: Aproximai-vos, levai os vossos irmãos de diante do santuário para fora do acampamento."},
{v:5,t:"Eles se aproximaram e os levaram nas suas túnicas para fora do acampamento, como Moisés dissera."},
{v:6,t:"Moisés disse a Aarão, e a Eleazar e Itamar, seus filhos: Não deixeis os cabelos em desalinho nem rasgueis as vossas vestes, para que não morrais e a ira não se acenda contra toda a comunidade. Os vossos irmãos, toda a casa de Israel, chorem pelo incêndio que o Senhor acendeu."},
{v:7,t:"Não saiais da entrada da tenda do encontro, para que não morrais, porque o óleo da unção do Senhor está sobre vós. E eles fizeram conforme a palavra de Moisés."},
{v:8,t:"O Senhor falou a Aarão, dizendo:"},
{v:9,t:"Não bebereis vinho nem bebida forte, nem tu nem teus filhos contigo, quando entrardes na tenda do encontro, para que não morrais: é preceito perpétuo pelas vossas gerações;"},
{v:10,t:"para que possais distinguir entre o santo e o profano, entre o impuro e o puro,"},
{v:11,t:"e ensinar aos filhos de Israel todos os preceitos que o Senhor lhes declarou por meio de Moisés."},
{v:12,t:"Moisés disse a Aarão, e a Eleazar e Itamar, os filhos que lhe restavam: Tomai a oblação que sobrou das ofertas queimadas ao Senhor e comei-a sem fermento junto ao altar, porque é coisa santíssima."},
{v:13,t:"Vós a comereis em lugar santo, porque é o direito que te cabe, a ti e a teus filhos, das ofertas queimadas ao Senhor; assim me foi ordenado."},
{v:14,t:"O peito da oferenda movida e a coxa da oferta elevada, vós os comereis em lugar puro, tu, teus filhos e tuas filhas contigo, porque são o direito que cabe a ti e a teus filhos, dos sacrifícios de comunhão dos filhos de Israel."},
{v:15,t:"A coxa da oferta elevada e o peito da oferenda movida, eles os trarão com as gorduras destinadas ao fogo, e os moverão com um gesto para a frente e para trás, como oferenda movida diante do Senhor; e serão teus e de teus filhos contigo, como direito perpétuo, conforme o Senhor ordenou."},
{v:16,t:"Moisés procurou com insistência o bode do sacrifício pelo pecado, e eis que já fora queimado. Irou-se então contra Eleazar e Itamar, os filhos que restavam a Aarão, e disse:"},
{v:17,t:"Por que não comestes o sacrifício pelo pecado em lugar santo? É coisa santíssima, e ele vos foi dado para carregardes a iniquidade da comunidade, fazendo expiação por ela diante do Senhor."},
{v:18,t:"Vede: o seu sangue não foi levado para dentro do santuário; devíeis tê-lo comido no santuário, como ordenei."},
{v:19,t:"Aarão respondeu a Moisés: Eis que hoje eles apresentaram o seu sacrifício pelo pecado e o seu holocausto diante do Senhor, e a mim sucederam tais coisas. Se eu tivesse comido hoje do sacrifício pelo pecado, teria isso agradado ao Senhor?"},
{v:20,t:"Ouvindo isto, Moisés deu-se por satisfeito."}
];

window.TEXTOS_SEED["levitico"][11] = [
{v:1,t:"O Senhor falou a Moisés e a Aarão, dizendo a eles:"},
{v:2,t:"Falai aos filhos de Israel: Estes são os animais que podereis comer, dentre todos os animais que há sobre a terra."},
{v:3,t:"Todo animal que tem o casco fendido, dividido em duas unhas, e que rumina, esse podereis comer."},
{v:4,t:"Mas, dentre os que ruminam ou têm o casco fendido, não comereis estes: o camelo, porque rumina mas não tem o casco fendido: será impuro para vós;"},
{v:5,t:"o damão, porque rumina mas não tem o casco fendido: será impuro para vós;",n:"Damão traduz shafan, pequeno mamífero das rochas (Procavia); a tradução antiga arganaz ou coelho é imprecisa. Ele não rumina de fato, mas o movimento contínuo das mandíbulas lhe dá essa aparência, e a lei fala segundo o que se observa."},
{v:6,t:"a lebre, porque rumina mas não tem o casco fendido: será impura para vós;"},
{v:7,t:"o porco, porque tem o casco fendido, dividido em duas unhas, mas não rumina: será impuro para vós."},
{v:8,t:"Da carne desses animais não comereis, nem tocareis os seus cadáveres: serão impuros para vós."},
{v:9,t:"Dentre todos os que vivem nas águas, podereis comer estes: tudo o que tem barbatanas e escamas, nas águas, nos mares e nos rios, isso podereis comer."},
{v:10,t:"Mas tudo o que não tem barbatanas e escamas, nos mares e nos rios, dentre tudo o que fervilha nas águas e dentre todos os seres vivos que nelas há, será para vós coisa abominável."},
{v:11,t:"Serão para vós abominação: não comereis da sua carne e tereis por abominável o seu cadáver."},
{v:12,t:"Tudo o que nas águas não tem barbatanas e escamas será para vós abominação."},
{v:13,t:"Dentre as aves, tereis por abominação estas, que não serão comidas, porque são abominação: a águia, o quebrantosso e a águia-marinha,",n:"A identificação exata de várias aves desta lista é incerta; sigo as equivalências mais prováveis, sem garantia zoológica em cada caso."},
{v:14,t:"o milhafre e o falcão, segundo a sua espécie,"},
{v:15,t:"todo corvo, segundo a sua espécie,"},
{v:16,t:"o avestruz, a coruja, a gaivota e o gavião, segundo a sua espécie,"},
{v:17,t:"o mocho, o corvo-marinho e a íbis,"},
{v:18,t:"a coruja-branca, o pelicano e o abutre,"},
{v:19,t:"a cegonha e a garça, segundo a sua espécie, a poupa e o morcego."},
{v:20,t:"Todo inseto alado que anda sobre quatro patas será para vós abominação."},
{v:21,t:"Contudo, dentre os insetos alados que andam sobre quatro patas, podereis comer aqueles que têm pernas acima dos pés, para saltar com elas sobre a terra."},
{v:22,t:"Destes podereis comer: o gafanhoto migrador, segundo a sua espécie, o gafanhoto devorador, segundo a sua espécie, o grilo, segundo a sua espécie, e a esperança, segundo a sua espécie.",n:"Os quatro nomes hebraicos (arbeh, solam, chargol, chagab) designam variedades de gafanhotos que já não sabemos distinguir com precisão; as equivalências são aproximadas."},
{v:23,t:"Mas todo outro inseto alado que tem quatro patas será para vós abominação."},
{v:24,t:"Por estes animais vos tornareis impuros: quem tocar o seu cadáver ficará impuro até a tarde,"},
{v:25,t:"e quem carregar o seu cadáver lavará as suas vestes e ficará impuro até a tarde."},
{v:26,t:"Todo animal que tem o casco fendido, mas não dividido em duas unhas, e que não rumina, será impuro para vós: quem o tocar ficará impuro."},
{v:27,t:"Todos os quadrúpedes que andam sobre as plantas dos pés serão impuros para vós: quem tocar o seu cadáver ficará impuro até a tarde,"},
{v:28,t:"e quem carregar o seu cadáver lavará as suas vestes e ficará impuro até a tarde: são impuros para vós."},
{v:29,t:"Dentre os pequenos animais que rastejam sobre a terra, estes serão impuros para vós: a doninha, o rato e o lagarto, segundo a sua espécie,"},
{v:30,t:"o geco, o lagarto-monitor, a lagartixa, o lagarto-da-areia e o camaleão.",n:"Também aqui a identificação dos répteis é conjetural; a lista hebraica enumera pequenos animais das casas e dos muros."},
{v:31,t:"Estes serão impuros para vós, dentre todos os que rastejam: quem tocar neles depois de mortos ficará impuro até a tarde."},
{v:32,t:"Tudo aquilo sobre o que cair um deles, morto, ficará impuro: utensílio de madeira, veste, pele, saco, qualquer objeto de uso; será mergulhado na água e ficará impuro até a tarde, e depois ficará puro."},
{v:33,t:"Se cair um deles dentro de qualquer vaso de barro, tudo o que estiver dentro dele ficará impuro, e quebrareis o vaso."},
{v:34,t:"Todo alimento que se come, sobre o qual cair dessa água, ficará impuro; e toda bebida que se bebe, em qualquer desses vasos, ficará impura."},
{v:35,t:"Tudo aquilo sobre o que cair parte do seu cadáver ficará impuro: forno e fogareiro serão demolidos; são impuros e impuros serão para vós."},
{v:36,t:"Contudo, a fonte e a cisterna, onde se recolhe água, permanecerão puras; mas quem tocar o cadáver ficará impuro."},
{v:37,t:"Se parte do seu cadáver cair sobre semente que vai ser semeada, ela permanecerá pura;"},
{v:38,t:"mas, se tiver sido posta água sobre a semente e sobre ela cair parte do seu cadáver, ela será impura para vós."},
{v:39,t:"Se morrer um dos animais que vos servem de alimento, quem tocar o seu cadáver ficará impuro até a tarde."},
{v:40,t:"Quem comer do seu cadáver lavará as suas vestes e ficará impuro até a tarde; e quem carregar o seu cadáver lavará as suas vestes e ficará impuro até a tarde."},
{v:41,t:"Todo animal que rasteja sobre a terra é coisa abominável: não será comido."},
{v:42,t:"Tudo o que anda sobre o ventre, tudo o que anda sobre quatro patas ou sobre muitas patas, dentre todos os animais que rastejam sobre a terra, não comereis, porque são abominação."},
{v:43,t:"Não vos torneis abomináveis por nenhum desses animais que rastejam; não vos contamineis com eles, para não vos tornardes impuros por meio deles."},
{v:44,t:"Porque eu sou o Senhor vosso Deus: santificai-vos e sede santos, porque eu sou santo; não contamineis as vossas almas com nenhum dos animais que rastejam sobre a terra."},
{v:45,t:"Porque eu sou o Senhor, que vos fiz subir da terra do Egito para ser o vosso Deus: sereis santos, porque eu sou santo."},
{v:46,t:"Esta é a lei acerca dos animais, das aves, de todo ser vivo que se move nas águas e de todo ser que rasteja sobre a terra,"},
{v:47,t:"para que se faça distinção entre o impuro e o puro, entre o animal que se pode comer e o animal que não se pode comer."}
];

window.TEXTOS_SEED["levitico"][12] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala aos filhos de Israel: Quando uma mulher conceber e der à luz um menino, ficará impura durante sete dias; ficará impura como nos dias da impureza da sua menstruação."},
{v:3,t:"No oitavo dia será circuncidada a carne do prepúcio do menino."},
{v:4,t:"Ela ficará ainda trinta e três dias no sangue da sua purificação; não tocará nenhuma coisa santa nem entrará no santuário, até que se completem os dias da sua purificação."},
{v:5,t:"Se der à luz uma menina, ficará impura durante duas semanas, como na sua menstruação, e ficará ainda sessenta e seis dias no sangue da sua purificação."},
{v:6,t:"Quando se completarem os dias da sua purificação, por filho ou por filha, trará ao sacerdote, à entrada da tenda do encontro, um cordeiro de um ano para holocausto e um pombinho ou uma rola para sacrifício pelo pecado."},
{v:7,t:"O sacerdote o apresentará diante do Senhor e fará expiação por ela, e ela ficará purificada do fluxo do seu sangue. Esta é a lei da mulher que dá à luz um menino ou uma menina."},
{v:8,t:"Se ela não tiver recursos para um cordeiro, tomará duas rolas ou dois pombinhos, um para holocausto e outro para sacrifício pelo pecado; o sacerdote fará expiação por ela, e ela ficará pura.",n:"Foi esta a oferta dos pobres que Maria apresentou na apresentação de Jesus no Templo (Lc 2, 24)."}
];

window.TEXTOS_SEED["levitico"][13] = [
{v:1,t:"O Senhor falou a Moisés e a Aarão, dizendo:"},
{v:2,t:"Quando alguém tiver na pele da sua carne um inchaço, uma erupção ou uma mancha luzente, e isso se tornar na pele da sua carne uma chaga de lepra, será levado ao sacerdote Aarão ou a um dos sacerdotes, seus filhos.",n:"Lepra traduz, segundo a tradição, o hebraico tsaraat, que abrange várias doenças da pele, e até manchas em roupas e paredes, e não coincide com a lepra da medicina moderna (hanseníase). Conservo o termo consagrado."},
{v:3,t:"O sacerdote examinará a chaga na pele da carne: se o pelo na chaga se tornou branco e a chaga parece mais profunda do que a pele da carne, é chaga de lepra; o sacerdote, ao examiná-lo, o declarará impuro."},
{v:4,t:"Se houver na pele da sua carne uma mancha luzente branca, mas que não pareça mais profunda do que a pele, e o pelo não se tiver tornado branco, o sacerdote isolará o doente durante sete dias."},
{v:5,t:"Ao sétimo dia o sacerdote o examinará: se a chaga lhe parecer estacionária, sem se estender pela pele, o sacerdote o isolará por mais sete dias."},
{v:6,t:"Ao sétimo dia o sacerdote o examinará de novo: se a chaga se tiver tornado baça e não se tiver estendido pela pele, o sacerdote o declarará puro: é uma erupção. Ele lavará as suas vestes e ficará puro."},
{v:7,t:"Mas, se a erupção se estender pela pele depois que ele se mostrou ao sacerdote para ser declarado puro, ele se mostrará outra vez ao sacerdote."},
{v:8,t:"O sacerdote o examinará: se a erupção se estendeu pela pele, o sacerdote o declarará impuro: é lepra."},
{v:9,t:"Quando houver em alguém uma chaga de lepra, será levado ao sacerdote."},
{v:10,t:"O sacerdote o examinará: se houver na pele um inchaço branco que tornou branco o pelo, e no inchaço houver carne viva,"},
{v:11,t:"é lepra inveterada na pele da sua carne: o sacerdote o declarará impuro; não o isolará, porque é evidentemente impuro."},
{v:12,t:"Mas, se a lepra se alastrar pela pele, de modo que cubra toda a pele do doente, da cabeça aos pés, até onde os olhos do sacerdote podem ver,"},
{v:13,t:"o sacerdote o examinará: se a lepra cobriu toda a sua carne, ele declarará puro o doente; tornou-se todo branco: está puro."},
{v:14,t:"Porém, no dia em que nele aparecer carne viva, ficará impuro."},
{v:15,t:"Quando o sacerdote vir a carne viva, o declarará impuro: a carne viva é impura, é lepra."},
{v:16,t:"Mas, se a carne viva mudar e se tornar branca, ele irá ao sacerdote;"},
{v:17,t:"o sacerdote o examinará: se a chaga se tornou branca, o sacerdote declarará puro o doente: está puro."},
{v:18,t:"Quando na pele da carne de alguém houver uma úlcera que sarou,"},
{v:19,t:"e no lugar da úlcera aparecer um inchaço branco ou uma mancha luzente branco-avermelhada, ele se mostrará ao sacerdote."},
{v:20,t:"O sacerdote o examinará: se a mancha parecer mais funda do que a pele e o seu pelo se tiver tornado branco, o sacerdote o declarará impuro: é chaga de lepra que brotou na úlcera."},
{v:21,t:"Mas, se o sacerdote, ao examiná-la, verificar que nela não há pelo branco, que não está mais funda do que a pele e que se tornou baça, o sacerdote o isolará durante sete dias."},
{v:22,t:"Se ela se estender pela pele, o sacerdote o declarará impuro: é chaga de lepra."},
{v:23,t:"Mas, se a mancha luzente permanecer no seu lugar, sem se estender, é a cicatriz da úlcera: o sacerdote o declarará puro."},
{v:24,t:"Quando alguém tiver na pele da carne uma queimadura de fogo, e sobre a queimadura se formar uma mancha luzente branco-avermelhada ou branca,"},
{v:25,t:"o sacerdote a examinará: se o pelo se tornou branco na mancha e ela parece mais funda do que a pele, é lepra que brotou na queimadura; o sacerdote o declarará impuro: é chaga de lepra."},
{v:26,t:"Mas, se o sacerdote, ao examiná-la, verificar que não há pelo branco na mancha, que ela não está mais funda do que a pele e que se tornou baça, o sacerdote o isolará durante sete dias."},
{v:27,t:"Ao sétimo dia o sacerdote o examinará: se a mancha se estendeu pela pele, o sacerdote o declarará impuro: é chaga de lepra."},
{v:28,t:"Mas, se a mancha luzente permanecer no seu lugar, sem se estender pela pele, e se tornar baça, é o inchaço da queimadura: o sacerdote o declarará puro, porque é a cicatriz da queimadura."},
{v:29,t:"Quando um homem ou uma mulher tiver uma chaga na cabeça ou na barba,"},
{v:30,t:"o sacerdote examinará a chaga: se ela parecer mais funda do que a pele, e nela houver pelo amarelado e fino, o sacerdote o declarará impuro: é tinha, é lepra da cabeça ou da barba."},
{v:31,t:"Mas, se o sacerdote, ao examinar a chaga da tinha, verificar que ela não parece mais funda do que a pele, embora nela não haja pelo negro, o sacerdote isolará durante sete dias o que tem a chaga da tinha."},
{v:32,t:"Ao sétimo dia o sacerdote examinará a chaga: se a tinha não se estendeu, se nela não há pelo amarelado e a tinha não parece mais funda do que a pele,"},
{v:33,t:"o doente se rapará, exceto no lugar da tinha, e o sacerdote o isolará por mais sete dias."},
{v:34,t:"Ao sétimo dia o sacerdote examinará a tinha: se ela não se estendeu pela pele e não parece mais funda do que a pele, o sacerdote o declarará puro; ele lavará as suas vestes e ficará puro."},
{v:35,t:"Mas, se a tinha se estender pela pele depois da sua purificação,"},
{v:36,t:"o sacerdote o examinará: se a tinha se estendeu pela pele, o sacerdote nem precisará procurar o pelo amarelado: ele é impuro."},
{v:37,t:"Se, porém, a seus olhos a tinha permanecer estacionária, e nela tiver crescido pelo negro, a tinha sarou: ele está puro, e o sacerdote o declarará puro."},
{v:38,t:"Quando um homem ou uma mulher tiver na pele da carne manchas luzentes, manchas brancas,"},
{v:39,t:"o sacerdote examinará: se as manchas na pele da carne são de um branco baço, é um eczema que brotou na pele: ele está puro."},
{v:40,t:"Quando a um homem caírem os cabelos da cabeça, é calvo: está puro."},
{v:41,t:"Se os cabelos lhe caírem da parte da frente da cabeça, é meio calvo: está puro."},
{v:42,t:"Mas, se na calva, atrás ou na frente, houver uma chaga branco-avermelhada, é lepra que brota na sua calva, atrás ou na frente."},
{v:43,t:"O sacerdote o examinará: se o inchaço da chaga, na sua calva, atrás ou na frente, é branco-avermelhado, com o aspecto da lepra da pele da carne,"},
{v:44,t:"o homem está leproso: é impuro. O sacerdote o declarará impuro: a sua chaga está na cabeça."},
{v:45,t:"O leproso atingido pela chaga trará as vestes rasgadas e os cabelos em desalinho, cobrirá o bigode e clamará: Impuro! Impuro!"},
{v:46,t:"Durante todo o tempo em que tiver a chaga, ficará impuro. É impuro: habitará sozinho, e a sua morada será fora do acampamento."},
{v:47,t:"Quando aparecer uma chaga de lepra numa veste, veste de lã ou veste de linho,"},
{v:48,t:"num tecido ou numa trama de linho ou de lã, numa pele ou em qualquer objeto de pele,"},
{v:49,t:"se a chaga na veste, na pele, no tecido, na trama ou em qualquer objeto de pele for esverdeada ou avermelhada, é chaga de lepra e será mostrada ao sacerdote."},
{v:50,t:"O sacerdote examinará a chaga e isolará durante sete dias o objeto atingido."},
{v:51,t:"Ao sétimo dia examinará a chaga: se a chaga se estendeu pela veste, pelo tecido, pela trama, pela pele ou por qualquer objeto feito de pele, é lepra corrosiva: o objeto é impuro."},
{v:52,t:"Ele queimará a veste, o tecido, a trama de lã ou de linho, ou qualquer objeto de pele em que estiver a chaga, porque é lepra corrosiva: será queimado no fogo."},
{v:53,t:"Mas, se o sacerdote verificar que a chaga não se estendeu pela veste, pelo tecido, pela trama ou por qualquer objeto de pele,"},
{v:54,t:"o sacerdote ordenará que se lave o objeto em que está a chaga e o isolará por mais sete dias."},
{v:55,t:"Depois de lavada a chaga, o sacerdote a examinará: se a chaga não mudou de aspecto, ainda que não se tenha estendido, o objeto é impuro; tu o queimarás no fogo: é uma corrosão, no direito ou no avesso."},
{v:56,t:"Mas, se o sacerdote verificar que a chaga, depois de lavada, se tornou baça, ele a rasgará da veste, da pele, do tecido ou da trama."},
{v:57,t:"Se ela tornar a aparecer na veste, no tecido, na trama ou em qualquer objeto de pele, é lepra que se alastra: queimarás no fogo o objeto em que está a chaga."},
{v:58,t:"A veste, o tecido, a trama ou qualquer objeto de pele que lavares e do qual a chaga desaparecer, será lavado pela segunda vez e ficará puro."},
{v:59,t:"Esta é a lei da chaga de lepra na veste de lã ou de linho, no tecido, na trama e em qualquer objeto de pele, para os declarar puros ou impuros."}
];

window.TEXTOS_SEED["levitico"][14] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Esta será a lei do leproso no dia da sua purificação: ele será levado ao sacerdote."},
{v:3,t:"O sacerdote sairá para fora do acampamento e o examinará: se a chaga da lepra sarou no leproso,"},
{v:4,t:"o sacerdote ordenará que se tomem, para aquele que se purifica, duas aves vivas e puras, madeira de cedro, carmesim e hissopo."},
{v:5,t:"O sacerdote ordenará que se imole uma das aves sobre um vaso de barro, com água viva.",n:"Água viva, isto é, água corrente de fonte, por oposição à água parada."},
{v:6,t:"Tomará a ave viva, a madeira de cedro, o carmesim e o hissopo, e os mergulhará, com a ave viva, no sangue da ave imolada sobre a água viva."},
{v:7,t:"Aspergirá sete vezes aquele que se purifica da lepra, o declarará puro e soltará a ave viva em campo aberto."},
{v:8,t:"Aquele que se purifica lavará as suas vestes, rapará todo o seu pelo, banhará o corpo na água e ficará puro. Depois entrará no acampamento, mas ficará fora da sua tenda durante sete dias."},
{v:9,t:"Ao sétimo dia rapará todo o seu pelo: os cabelos, a barba e as sobrancelhas, todo o seu pelo rapará; lavará as suas vestes, banhará o corpo na água e ficará puro."},
{v:10,t:"No oitavo dia tomará dois cordeiros sem defeito, uma ovelha de um ano sem defeito, três décimos de efá de flor de farinha amassada com azeite, como oblação, e um log de azeite.",n:"O log era medida de líquidos de cerca de um terço de litro."},
{v:11,t:"O sacerdote que faz a purificação apresentará o homem que se purifica, com tudo isso, diante do Senhor, à entrada da tenda do encontro."},
{v:12,t:"O sacerdote tomará um dos cordeiros e o apresentará como sacrifício de reparação, com o log de azeite, e os moverá com um gesto para a frente e para trás, como oferenda movida diante do Senhor."},
{v:13,t:"Imolará o cordeiro no lugar onde se imolam o sacrifício pelo pecado e o holocausto, no lugar santo; porque, como o sacrifício pelo pecado, também o sacrifício de reparação pertence ao sacerdote: é coisa santíssima."},
{v:14,t:"O sacerdote tomará do sangue do sacrifício de reparação e o porá sobre o lóbulo da orelha direita daquele que se purifica, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito."},
{v:15,t:"O sacerdote tomará do log de azeite e o derramará na palma da sua própria mão esquerda;"},
{v:16,t:"molhará o dedo direito no azeite que está na palma da sua mão esquerda e com o dedo aspergirá do azeite sete vezes diante do Senhor."},
{v:17,t:"Do azeite que restar na palma da sua mão, o sacerdote porá sobre o lóbulo da orelha direita daquele que se purifica, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito, por cima do sangue do sacrifício de reparação."},
{v:18,t:"O que ainda restar do azeite na palma da mão do sacerdote, ele o porá sobre a cabeça daquele que se purifica; assim o sacerdote fará expiação por ele diante do Senhor."},
{v:19,t:"Depois o sacerdote fará o sacrifício pelo pecado e fará expiação por aquele que se purifica da sua impureza; em seguida imolará o holocausto."},
{v:20,t:"O sacerdote oferecerá o holocausto e a oblação sobre o altar; o sacerdote fará expiação por ele, e ele ficará puro."},
{v:21,t:"Se for pobre e não tiver recursos, tomará um só cordeiro, como sacrifício de reparação, para ser movido em oferenda e fazer expiação por ele; um décimo de efá de flor de farinha amassada com azeite, como oblação, e um log de azeite;"},
{v:22,t:"e duas rolas ou dois pombinhos, conforme os seus recursos: um será para o sacrifício pelo pecado e o outro para o holocausto."},
{v:23,t:"No oitavo dia da sua purificação, ele os trará ao sacerdote, à entrada da tenda do encontro, diante do Senhor."},
{v:24,t:"O sacerdote tomará o cordeiro do sacrifício de reparação e o log de azeite, e os moverá com um gesto para a frente e para trás, como oferenda movida diante do Senhor."},
{v:25,t:"Imolará o cordeiro do sacrifício de reparação, tomará do sangue do sacrifício de reparação e o porá sobre o lóbulo da orelha direita daquele que se purifica, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito."},
{v:26,t:"O sacerdote derramará do azeite na palma da sua própria mão esquerda"},
{v:27,t:"e, com o dedo direito, aspergirá do azeite que está na palma da sua mão esquerda sete vezes diante do Senhor."},
{v:28,t:"O sacerdote porá do azeite que está na palma da sua mão sobre o lóbulo da orelha direita daquele que se purifica, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito, no mesmo lugar do sangue do sacrifício de reparação."},
{v:29,t:"O que restar do azeite na palma da mão do sacerdote, ele o porá sobre a cabeça daquele que se purifica, para fazer expiação por ele diante do Senhor."},
{v:30,t:"Depois oferecerá uma das rolas ou um dos pombinhos, conforme os seus recursos,"},
{v:31,t:"um como sacrifício pelo pecado e o outro como holocausto, junto com a oblação; assim o sacerdote fará expiação, diante do Senhor, por aquele que se purifica."},
{v:32,t:"Esta é a lei daquele que tem chaga de lepra e não tem recursos para a sua purificação."},
{v:33,t:"O Senhor falou a Moisés e a Aarão, dizendo:"},
{v:34,t:"Quando tiverdes entrado na terra de Canaã, que vos dou em possessão, se eu puser uma chaga de lepra numa casa da terra da vossa possessão,"},
{v:35,t:"o dono da casa irá informar o sacerdote, dizendo: Parece-me que há como que uma chaga na minha casa."},
{v:36,t:"O sacerdote ordenará que esvaziem a casa antes de ele entrar para examinar a chaga, para que não se torne impuro tudo o que há na casa; depois o sacerdote entrará para examinar a casa."},
{v:37,t:"Examinará a chaga: se a chaga que está nas paredes da casa consiste em cavidades esverdeadas ou avermelhadas, que parecem mais fundas do que a parede,"},
{v:38,t:"o sacerdote sairá da casa, para a porta, e fechará a casa durante sete dias."},
{v:39,t:"Ao sétimo dia o sacerdote voltará e examinará: se a chaga se estendeu pelas paredes da casa,"},
{v:40,t:"o sacerdote ordenará que arranquem as pedras em que está a chaga e as lancem fora da cidade, num lugar impuro."},
{v:41,t:"Fará raspar a casa por dentro, ao redor, e o pó raspado será despejado fora da cidade, num lugar impuro."},
{v:42,t:"Tomarão outras pedras e as porão no lugar das primeiras, e com outra argamassa se rebocará a casa."},
{v:43,t:"Se a chaga tornar a brotar na casa, depois de arrancadas as pedras, raspada e rebocada a casa,"},
{v:44,t:"o sacerdote entrará e examinará: se a chaga se estendeu pela casa, é lepra corrosiva na casa: ela é impura."},
{v:45,t:"Demolirão a casa, e as suas pedras, a sua madeira e toda a argamassa da casa serão levadas para fora da cidade, a um lugar impuro."},
{v:46,t:"Quem entrar na casa durante os dias em que estiver fechada ficará impuro até a tarde."},
{v:47,t:"Quem dormir na casa lavará as suas vestes, e quem comer na casa lavará as suas vestes."},
{v:48,t:"Mas, se o sacerdote entrar e examinar, e a chaga não se tiver estendido pela casa depois de rebocada, o sacerdote declarará pura a casa, porque a chaga sarou."},
{v:49,t:"Para purificar a casa, tomará duas aves, madeira de cedro, carmesim e hissopo."},
{v:50,t:"Imolará uma das aves sobre um vaso de barro, com água viva."},
{v:51,t:"Tomará a madeira de cedro, o hissopo, o carmesim e a ave viva, e os mergulhará no sangue da ave imolada e na água viva, e aspergirá a casa sete vezes."},
{v:52,t:"Purificará a casa com o sangue da ave, com a água viva, com a ave viva, com a madeira de cedro, com o hissopo e com o carmesim."},
{v:53,t:"Depois soltará a ave viva fora da cidade, em campo aberto; assim fará expiação pela casa, e ela ficará pura."},
{v:54,t:"Esta é a lei de toda chaga de lepra e da tinha,"},
{v:55,t:"da lepra das vestes e das casas,"},
{v:56,t:"dos inchaços, das erupções e das manchas luzentes,"},
{v:57,t:"para ensinar quando algo é impuro e quando é puro. Esta é a lei da lepra."}
];

window.TEXTOS_SEED["levitico"][15] = [
{v:1,t:"O Senhor falou a Moisés e a Aarão, dizendo:"},
{v:2,t:"Falai aos filhos de Israel e dizei a eles: Quando um homem tiver um fluxo que sai da sua carne, esse fluxo é impuro."},
{v:3,t:"Esta será a sua impureza em razão do fluxo: quer a sua carne deixe correr o fluxo, quer o retenha, há impureza."},
{v:4,t:"Toda cama em que se deitar o que tem o fluxo ficará impura, e todo objeto sobre o qual se sentar ficará impuro."},
{v:5,t:"Quem tocar a sua cama lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:6,t:"Quem se sentar sobre o objeto em que se sentou o que tem o fluxo lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:7,t:"Quem tocar a carne do que tem o fluxo lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:8,t:"Se o que tem o fluxo cuspir sobre alguém que está puro, este lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:9,t:"Toda sela em que montar o que tem o fluxo ficará impura."},
{v:10,t:"Quem tocar qualquer coisa que tenha estado debaixo dele ficará impuro até a tarde, e quem a carregar lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:11,t:"Todo aquele que for tocado pelo que tem o fluxo, sem que este tenha lavado as mãos com água, lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:12,t:"O vaso de barro que o que tem o fluxo tocar será quebrado, e todo utensílio de madeira será lavado com água."},
{v:13,t:"Quando o que tem o fluxo ficar purificado do seu fluxo, contará sete dias para a sua purificação; lavará as suas vestes, banhará o corpo em água viva e ficará puro."},
{v:14,t:"No oitavo dia tomará duas rolas ou dois pombinhos, virá diante do Senhor, à entrada da tenda do encontro, e os dará ao sacerdote."},
{v:15,t:"O sacerdote os oferecerá, um como sacrifício pelo pecado e o outro como holocausto; assim o sacerdote fará expiação por ele, diante do Senhor, por causa do seu fluxo."},
{v:16,t:"Quando de um homem sair a emissão do sêmen, ele banhará todo o corpo na água e ficará impuro até a tarde."},
{v:17,t:"Toda veste e toda pele sobre a qual houver emissão de sêmen serão lavadas com água e ficarão impuras até a tarde."},
{v:18,t:"Quando um homem se deitar com uma mulher e houver emissão de sêmen, ambos se banharão na água e ficarão impuros até a tarde."},
{v:19,t:"Quando uma mulher tiver um fluxo, e o fluxo na sua carne for de sangue, ficará sete dias na sua impureza; quem a tocar ficará impuro até a tarde."},
{v:20,t:"Tudo sobre o que ela se deitar durante a sua impureza ficará impuro, e tudo sobre o que se sentar ficará impuro."},
{v:21,t:"Quem tocar a sua cama lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:22,t:"Quem tocar qualquer objeto sobre o qual ela se tiver sentado lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:23,t:"Se algo estiver sobre a cama ou sobre o objeto em que ela se sentou, quem o tocar ficará impuro até a tarde."},
{v:24,t:"Se um homem se deitar com ela e a impureza dela o atingir, ficará impuro durante sete dias, e toda cama em que se deitar ficará impura."},
{v:25,t:"Quando uma mulher tiver um fluxo de sangue durante muitos dias, fora do tempo da sua menstruação, ou um fluxo que se prolongue além da sua menstruação, ficará impura durante todos os dias do fluxo da sua impureza, como nos dias da sua menstruação."},
{v:26,t:"Toda cama em que se deitar durante os dias do seu fluxo será para ela como a cama da sua menstruação, e todo objeto sobre o qual se sentar ficará impuro, como na impureza da sua menstruação."},
{v:27,t:"Quem tocar essas coisas ficará impuro; lavará as suas vestes, banhará o corpo na água e ficará impuro até a tarde."},
{v:28,t:"Quando ela ficar purificada do seu fluxo, contará sete dias e depois ficará pura."},
{v:29,t:"No oitavo dia tomará duas rolas ou dois pombinhos e os levará ao sacerdote, à entrada da tenda do encontro."},
{v:30,t:"O sacerdote oferecerá um como sacrifício pelo pecado e o outro como holocausto; assim o sacerdote fará expiação por ela, diante do Senhor, por causa do fluxo da sua impureza."},
{v:31,t:"Assim mantereis os filhos de Israel separados das suas impurezas, para que não morram por causa das suas impurezas, contaminando a minha morada, que está no meio deles."},
{v:32,t:"Esta é a lei daquele que tem um fluxo, daquele de quem sai a emissão do sêmen, tornando-se impuro por ela,"},
{v:33,t:"da mulher indisposta na sua menstruação, de quem tem um fluxo, seja homem ou mulher, e do homem que se deita com uma mulher impura."}
];

window.TEXTOS_SEED["levitico"][16] = [
{v:1,t:"O Senhor falou a Moisés depois da morte dos dois filhos de Aarão, que morreram ao se aproximarem da presença do Senhor."},
{v:2,t:"O Senhor disse a Moisés: Fala a Aarão, teu irmão, que não entre em qualquer tempo no santuário, para dentro do véu, diante do propiciatório que está sobre a arca, para que não morra; porque eu apareço na nuvem, sobre o propiciatório.",n:"Propiciatório traduz kapporet, a tampa de ouro da arca, lugar da expiação (kipper); a tradição grega verteu por hilasterion, termo que São Paulo aplica a Cristo (Rm 3, 25)."},
{v:3,t:"Aarão entrará no santuário deste modo: com um novilho para sacrifício pelo pecado e um carneiro para holocausto."},
{v:4,t:"Vestirá a túnica sagrada de linho, terá sobre o corpo os calções de linho, ele se cingirá com o cinto de linho e porá na cabeça o turbante de linho: são vestes sagradas; ele banhará o corpo na água e as vestirá."},
{v:5,t:"Receberá da comunidade dos filhos de Israel dois bodes para sacrifício pelo pecado e um carneiro para holocausto."},
{v:6,t:"Aarão oferecerá o novilho do sacrifício pelo seu próprio pecado e fará expiação por si e pela sua casa."},
{v:7,t:"Tomará os dois bodes e os colocará diante do Senhor, à entrada da tenda do encontro."},
{v:8,t:"Aarão lançará sortes sobre os dois bodes: uma sorte para o Senhor e outra sorte para Azazel.",n:"Azazel: nome de sentido discutido; ou o próprio bode que é enviado (donde a tradução antiga bode emissário), ou o lugar escarpado do deserto, ou um demônio do deserto ao qual se remete simbolicamente o pecado. Conservei a transliteração."},
{v:9,t:"Aarão apresentará o bode sobre o qual caiu a sorte para o Senhor e o oferecerá como sacrifício pelo pecado."},
{v:10,t:"Mas o bode sobre o qual caiu a sorte para Azazel será colocado vivo diante do Senhor, para fazer sobre ele a expiação e o enviar a Azazel, ao deserto."},
{v:11,t:"Aarão apresentará o novilho do sacrifício pelo seu próprio pecado e fará expiação por si e pela sua casa; e imolará o novilho do sacrifício pelo seu pecado."},
{v:12,t:"Tomará o incensário cheio de brasas do altar que está diante do Senhor, e as suas mãos cheias de incenso aromático em pó, e os levará para dentro do véu."},
{v:13,t:"Porá o incenso sobre o fogo, diante do Senhor, para que a nuvem do incenso cubra o propiciatório que está sobre o testemunho, e ele não morra."},
{v:14,t:"Tomará do sangue do novilho e o aspergirá com o dedo sobre a face do propiciatório, do lado do oriente; e diante do propiciatório aspergirá do sangue sete vezes com o dedo."},
{v:15,t:"Depois imolará o bode do sacrifício pelo pecado do povo e levará o seu sangue para dentro do véu; fará com esse sangue como fez com o sangue do novilho: aspergirá com ele o propiciatório e diante do propiciatório."},
{v:16,t:"Assim fará expiação pelo santuário, por causa das impurezas dos filhos de Israel, das suas transgressões e de todos os seus pecados; o mesmo fará pela tenda do encontro, que permanece com eles no meio das suas impurezas."},
{v:17,t:"Ninguém estará na tenda do encontro quando ele entrar para fazer a expiação no santuário, até que saia; ele fará expiação por si, pela sua casa e por toda a assembleia de Israel."},
{v:18,t:"Depois sairá para o altar que está diante do Senhor e fará expiação por ele: tomará do sangue do novilho e do sangue do bode e o porá sobre os chifres do altar, ao redor."},
{v:19,t:"Com o dedo aspergirá sobre ele do sangue sete vezes; assim o purificará e o santificará das impurezas dos filhos de Israel."},
{v:20,t:"Quando tiver acabado de fazer a expiação pelo santuário, pela tenda do encontro e pelo altar, apresentará o bode vivo."},
{v:21,t:"Aarão porá as duas mãos sobre a cabeça do bode vivo e confessará sobre ele todas as iniquidades dos filhos de Israel, todas as suas transgressões e todos os seus pecados; ele os porá sobre a cabeça do bode e o enviará ao deserto, pela mão de um homem designado para isso."},
{v:22,t:"O bode levará sobre si todas as iniquidades deles para uma terra solitária, e o homem soltará o bode no deserto."},
{v:23,t:"Depois Aarão entrará na tenda do encontro, despirá as vestes de linho que vestira ao entrar no santuário e as deixará ali."},
{v:24,t:"Banhará o corpo na água, em lugar santo, e vestirá as suas vestes; sairá, fará o seu holocausto e o holocausto do povo, e fará expiação por si e pelo povo."},
{v:25,t:"Queimará sobre o altar a gordura do sacrifício pelo pecado."},
{v:26,t:"Aquele que tiver conduzido o bode a Azazel lavará as suas vestes e banhará o corpo na água; depois disso entrará no acampamento."},
{v:27,t:"O novilho do sacrifício pelo pecado e o bode do sacrifício pelo pecado, cujo sangue foi levado para fazer a expiação no santuário, serão levados para fora do acampamento, e serão queimados no fogo os seus couros, as suas carnes e os seus excrementos.",n:"A Carta aos Hebreus (13, 11-12) vê nesta queima fora do acampamento a figura de Cristo, que padeceu fora da porta da cidade."},
{v:28,t:"Aquele que os queimar lavará as suas vestes e banhará o corpo na água; depois disso entrará no acampamento."},
{v:29,t:"Isto será para vós preceito perpétuo: no sétimo mês, no décimo dia do mês, afligireis as vossas almas e não fareis trabalho algum, nem o natural da terra nem o estrangeiro que mora no meio de vós.",n:"Afligir a alma é a expressão consagrada para o jejum e a penitência do dia da Expiação (Yom Kippur)."},
{v:30,t:"Porque nesse dia se fará expiação por vós, para vos purificar: de todos os vossos pecados ficareis puros diante do Senhor."},
{v:31,t:"É para vós sábado de repouso completo, e afligireis as vossas almas: é preceito perpétuo."},
{v:32,t:"Fará a expiação o sacerdote que tiver sido ungido e investido para exercer o sacerdócio no lugar de seu pai; ele vestirá as vestes de linho, as vestes sagradas."},
{v:33,t:"Fará expiação pelo santuário santíssimo, fará expiação pela tenda do encontro e pelo altar, e fará expiação pelos sacerdotes e por todo o povo da assembleia."},
{v:34,t:"Isto será para vós preceito perpétuo: fazer expiação pelos filhos de Israel, por todos os seus pecados, uma vez por ano. E fez-se como o Senhor ordenara a Moisés."}
];

window.TEXTOS_SEED["levitico"][17] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala a Aarão, a seus filhos e a todos os filhos de Israel, e dize a eles: Esta é a palavra que o Senhor ordenou, dizendo:"},
{v:3,t:"Qualquer homem da casa de Israel que imolar um boi, um cordeiro ou uma cabra, dentro do acampamento ou fora do acampamento,"},
{v:4,t:"e não o trouxer à entrada da tenda do encontro, para o apresentar como oferta ao Senhor diante da morada do Senhor, será considerado réu de sangue: derramou sangue, e esse homem será eliminado do meio do seu povo;"},
{v:5,t:"para que os filhos de Israel tragam os sacrifícios que imolam em pleno campo, para que os tragam ao Senhor, à entrada da tenda do encontro, ao sacerdote, e os imolem como sacrifícios de comunhão ao Senhor."},
{v:6,t:"O sacerdote derramará o sangue sobre o altar do Senhor, à entrada da tenda do encontro, e queimará a gordura em aroma agradável ao Senhor."},
{v:7,t:"E não imolarão mais os seus sacrifícios aos sátiros, atrás dos quais se prostituem: isto será para eles preceito perpétuo pelas suas gerações.",n:"Sátiros traduz seirim, literalmente os peludos: os demônios em figura de bode, cultuados nos campos."},
{v:8,t:"Dize a eles ainda: Qualquer homem da casa de Israel, ou dos estrangeiros que moram no meio deles, que oferecer holocausto ou sacrifício,"},
{v:9,t:"e não o trouxer à entrada da tenda do encontro, para o oferecer ao Senhor, esse homem será eliminado do seu povo."},
{v:10,t:"Qualquer homem da casa de Israel, ou dos estrangeiros que moram no meio deles, que comer qualquer sangue, contra esse que come o sangue voltarei a minha face e o eliminarei do meio do seu povo."},
{v:11,t:"Porque a alma da carne está no sangue, e eu vos dei o sangue sobre o altar, para fazer expiação pelas vossas almas; porque é o sangue que faz expiação pela alma.",n:"Alma traduz nefesh, o princípio vital; o versículo é a chave de toda a teologia sacrificial do livro e do sentido expiatório do sangue de Cristo."},
{v:12,t:"Por isso disse aos filhos de Israel: Nenhum de vós comerá sangue, nem o estrangeiro que mora no meio de vós comerá sangue."},
{v:13,t:"Qualquer homem dos filhos de Israel, ou dos estrangeiros que moram no meio deles, que caçar um animal ou uma ave que se pode comer, derramará o seu sangue e o cobrirá com terra."},
{v:14,t:"Porque a alma de toda carne é o seu sangue: nele está a sua alma. Por isso disse aos filhos de Israel: Não comereis o sangue de carne alguma, porque a alma de toda carne é o seu sangue; quem o comer será eliminado."},
{v:15,t:"Toda pessoa, natural da terra ou estrangeira, que comer um animal morto ou dilacerado, lavará as suas vestes, banhará o corpo na água e ficará impura até a tarde; depois ficará pura."},
{v:16,t:"Se não lavar as vestes nem banhar o corpo, carregará a sua iniquidade."}
];

window.TEXTOS_SEED["levitico"][18] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala aos filhos de Israel e dize a eles: Eu sou o Senhor vosso Deus."},
{v:3,t:"Não fareis como se faz na terra do Egito, onde habitastes, nem fareis como se faz na terra de Canaã, para onde vos levo; não andareis segundo os seus costumes."},
{v:4,t:"Praticareis os meus juízos e guardareis os meus preceitos, andando neles. Eu sou o Senhor vosso Deus."},
{v:5,t:"Guardareis os meus preceitos e os meus juízos: o homem que os praticar viverá por eles. Eu sou o Senhor.",n:"Versículo citado por São Paulo (Rm 10, 5; Gl 3, 12) como síntese da justiça que vem da lei."},
{v:6,t:"Nenhum de vós se aproximará daquela que é sua parenta próxima, para descobrir a sua nudez. Eu sou o Senhor.",n:"Descobrir a nudez é o eufemismo hebraico para a união carnal; conservei a expressão literal, que estrutura todo o capítulo."},
{v:7,t:"Não descobrirás a nudez de teu pai nem a nudez de tua mãe: ela é tua mãe, não descobrirás a sua nudez."},
{v:8,t:"Não descobrirás a nudez da mulher de teu pai: é a nudez de teu pai."},
{v:9,t:"Não descobrirás a nudez de tua irmã, filha de teu pai ou filha de tua mãe, nascida em casa ou nascida fora."},
{v:10,t:"Não descobrirás a nudez da filha de teu filho ou da filha de tua filha, porque é a tua própria nudez."},
{v:11,t:"Não descobrirás a nudez da filha da mulher de teu pai, gerada por teu pai: é tua irmã."},
{v:12,t:"Não descobrirás a nudez da irmã de teu pai: é carne de teu pai."},
{v:13,t:"Não descobrirás a nudez da irmã de tua mãe: é carne de tua mãe."},
{v:14,t:"Não descobrirás a nudez do irmão de teu pai: não te aproximarás da sua mulher; ela é tua tia."},
{v:15,t:"Não descobrirás a nudez de tua nora: é a mulher de teu filho, não descobrirás a sua nudez."},
{v:16,t:"Não descobrirás a nudez da mulher de teu irmão: é a nudez de teu irmão."},
{v:17,t:"Não descobrirás a nudez de uma mulher e de sua filha; não tomarás a filha do filho dela nem a filha da filha dela, para descobrir a sua nudez: são a sua própria carne; é uma infâmia."},
{v:18,t:"Não tomarás uma mulher junto com a sua irmã, fazendo dela rival, descobrindo a sua nudez enquanto a primeira vive."},
{v:19,t:"Não te aproximarás de uma mulher durante a impureza da sua menstruação, para descobrir a sua nudez."},
{v:20,t:"Não te deitarás com a mulher do teu próximo, para não te tornares impuro com ela."},
{v:21,t:"Não darás nenhum dos teus filhos para ser oferecido a Moloc, e não profanarás o nome do teu Deus. Eu sou o Senhor.",n:"Moloc: divindade a quem se imolavam crianças pelo fogo; o texto diz literalmente fazer passar a Moloc, alusão ao rito de fazer passar os filhos pelo fogo."},
{v:22,t:"Não te deitarás com um homem como quem se deita com uma mulher: é abominação."},
{v:23,t:"Não te unirás a nenhum animal, para não te tornares impuro com ele, nem a mulher se porá diante de um animal para se unir a ele: é uma perversão."},
{v:24,t:"Não vos contamineis com nenhuma dessas coisas, porque com todas elas se contaminaram as nações que expulso de diante de vós."},
{v:25,t:"A terra ficou contaminada; eu castiguei a sua iniquidade, e a terra vomitou os seus habitantes."},
{v:26,t:"Vós, porém, guardareis os meus preceitos e os meus juízos, e não cometereis nenhuma dessas abominações, nem o natural da terra nem o estrangeiro que mora no meio de vós;"},
{v:27,t:"porque todas essas abominações cometeram os homens daquela terra que ali estavam antes de vós, e a terra ficou contaminada."},
{v:28,t:"Que a terra não vos vomite também, por a contaminardes, como vomitou a nação que ali estava antes de vós."},
{v:29,t:"Porque todo aquele que cometer qualquer dessas abominações será eliminado do meio do seu povo."},
{v:30,t:"Guardareis, pois, a minha observância, não praticando nenhum dos costumes abomináveis que se praticaram antes de vós, e não vos contaminareis com eles. Eu sou o Senhor vosso Deus."}
];

window.TEXTOS_SEED["levitico"][19] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala a toda a comunidade dos filhos de Israel e dize a eles: Sede santos, porque eu, o Senhor vosso Deus, sou santo."},
{v:3,t:"Cada um de vós tema a sua mãe e o seu pai, e guardai os meus sábados. Eu sou o Senhor vosso Deus."},
{v:4,t:"Não vos volteis para os ídolos nem façais para vós deuses de metal fundido. Eu sou o Senhor vosso Deus."},
{v:5,t:"Quando imolardes um sacrifício de comunhão ao Senhor, vós o imolareis de modo que seja aceito em vosso favor."},
{v:6,t:"Será comido no dia em que o imolardes, e no dia seguinte; o que sobrar até o terceiro dia será queimado no fogo."},
{v:7,t:"Se alguma coisa dele for comida ao terceiro dia, é carne corrompida: não será aceito."},
{v:8,t:"Quem o comer carregará a sua iniquidade, porque profanou o que é santo para o Senhor: essa pessoa será eliminada do seu povo."},
{v:9,t:"Quando fizerdes a colheita da vossa terra, não segarás o teu campo até a beirada nem recolherás as espigas caídas da tua colheita."},
{v:10,t:"Não rebuscarás a tua vinha nem recolherás os bagos caídos da tua vinha: tu os deixarás para o pobre e para o estrangeiro. Eu sou o Senhor vosso Deus."},
{v:11,t:"Não furtareis, não mentireis nem enganareis cada um ao seu próximo."},
{v:12,t:"Não jurareis falso pelo meu nome, profanando o nome do teu Deus. Eu sou o Senhor."},
{v:13,t:"Não oprimirás o teu próximo nem o despojarás; a paga do diarista não ficará contigo até a manhã seguinte."},
{v:14,t:"Não amaldiçoarás o surdo nem porás tropeço diante do cego, mas temerás o teu Deus. Eu sou o Senhor."},
{v:15,t:"Não cometereis injustiça no julgamento: não favorecerás o pobre nem honrarás o poderoso; com justiça julgarás o teu próximo."},
{v:16,t:"Não andarás espalhando calúnias no meio do teu povo, nem te levantarás contra o sangue do teu próximo. Eu sou o Senhor."},
{v:17,t:"Não odiarás o teu irmão no teu coração; repreenderás francamente o teu próximo, para não carregares pecado por causa dele."},
{v:18,t:"Não te vingarás nem guardarás rancor contra os filhos do teu povo; amarás o teu próximo como a ti mesmo. Eu sou o Senhor.",n:"O mandamento que o Senhor Jesus declara segundo e semelhante ao primeiro (Mt 22, 39), do qual dependem toda a Lei e os Profetas."},
{v:19,t:"Guardareis os meus preceitos. Não cruzarás o teu gado com animais de espécie diferente; não semearás o teu campo com duas espécies de semente; não vestirás roupa tecida de dois estambres diferentes."},
{v:20,t:"Quando um homem se deitar com uma mulher que seja escrava prometida a outro homem, sem ter sido resgatada nem posta em liberdade, haverá castigo; mas não morrerão, porque ela não era livre.",n:"Haverá castigo traduz o obscuro biqqoret, termo único na Escritura: ou inquérito, ou indenização, ou castigo corporal; a Nova Vulgata entende que ambos serão açoitados."},
{v:21,t:"Ele trará ao Senhor, à entrada da tenda do encontro, um carneiro como sacrifício de reparação."},
{v:22,t:"Com o carneiro do sacrifício de reparação o sacerdote fará expiação por ele diante do Senhor, pelo pecado que cometeu; e lhe será perdoado o pecado que cometeu."},
{v:23,t:"Quando entrardes na terra e plantardes toda espécie de árvores frutíferas, considerareis os seus frutos como incircuncisos: durante três anos serão para vós incircuncisos, e não se comerá deles."},
{v:24,t:"No quarto ano, todos os seus frutos serão consagrados em louvor ao Senhor."},
{v:25,t:"No quinto ano comereis os seus frutos, para que a sua produção aumente em vosso favor. Eu sou o Senhor vosso Deus."},
{v:26,t:"Não comereis nada com sangue. Não praticareis adivinhação nem observareis presságios."},
{v:27,t:"Não cortareis o cabelo em redondo, nas têmporas, nem danificarás as pontas da tua barba."},
{v:28,t:"Não fareis incisões na vossa carne por causa de um morto, nem fareis tatuagens sobre vós. Eu sou o Senhor."},
{v:29,t:"Não profanarás a tua filha, fazendo dela uma prostituta, para que a terra não se prostitua e não se encha de infâmia."},
{v:30,t:"Guardareis os meus sábados e reverenciareis o meu santuário. Eu sou o Senhor."},
{v:31,t:"Não vos volteis para os necromantes nem consulteis os adivinhos, para não vos contaminardes com eles. Eu sou o Senhor vosso Deus."},
{v:32,t:"Diante das cãs te levantarás, honrarás a pessoa do ancião e temerás o teu Deus. Eu sou o Senhor."},
{v:33,t:"Quando um estrangeiro morar convosco na vossa terra, não o oprimireis."},
{v:34,t:"O estrangeiro que mora convosco será para vós como o natural da terra, e tu o amarás como a ti mesmo, porque fostes estrangeiros na terra do Egito. Eu sou o Senhor vosso Deus."},
{v:35,t:"Não cometereis injustiça no julgamento, nem nas medidas de comprimento, de peso ou de capacidade."},
{v:36,t:"Tereis balanças justas, pesos justos, efá justo e him justo. Eu sou o Senhor vosso Deus, que vos fiz sair da terra do Egito.",n:"O him era medida de líquidos de cerca de quatro litros; o efá, de secos, cerca de vinte e dois litros."},
{v:37,t:"Guardareis todos os meus preceitos e todos os meus juízos, e os praticareis. Eu sou o Senhor."}
];

window.TEXTOS_SEED["levitico"][20] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Dirás aos filhos de Israel: Qualquer homem dos filhos de Israel, ou dos estrangeiros que moram em Israel, que der um dos seus filhos a Moloc, será morto: o povo da terra o apedrejará."},
{v:3,t:"Eu voltarei a minha face contra esse homem e o eliminarei do meio do seu povo, porque deu um dos seus filhos a Moloc, contaminando o meu santuário e profanando o meu santo nome."},
{v:4,t:"Se o povo da terra fechar os olhos diante desse homem que deu um dos seus filhos a Moloc, e não o matar,"},
{v:5,t:"eu mesmo voltarei a minha face contra esse homem e contra a sua família, e o eliminarei do meio do seu povo, a ele e a todos os que, atrás dele, se prostituírem seguindo Moloc."},
{v:6,t:"Se alguém se voltar para os necromantes e para os adivinhos, prostituindo-se atrás deles, voltarei a minha face contra essa pessoa e a eliminarei do meio do seu povo."},
{v:7,t:"Santificai-vos e sede santos, porque eu sou o Senhor vosso Deus."},
{v:8,t:"Guardareis os meus preceitos e os praticareis. Eu sou o Senhor, que vos santifico."},
{v:9,t:"Todo aquele que amaldiçoar o seu pai ou a sua mãe será morto: amaldiçoou o seu pai ou a sua mãe; o seu sangue está sobre ele."},
{v:10,t:"O homem que cometer adultério com a mulher de outro, que cometer adultério com a mulher do seu próximo, será morto: o adúltero e a adúltera."},
{v:11,t:"O homem que se deitar com a mulher do seu pai descobriu a nudez do seu pai: ambos serão mortos; o seu sangue está sobre eles."},
{v:12,t:"Se um homem se deitar com a sua nora, ambos serão mortos: cometeram uma perversão; o seu sangue está sobre eles."},
{v:13,t:"Se um homem se deitar com outro homem como quem se deita com uma mulher, ambos cometeram abominação: serão mortos; o seu sangue está sobre eles."},
{v:14,t:"Se um homem tomar por mulher a filha e a mãe, é uma infâmia: ele e elas serão queimados no fogo, para que não haja tal infâmia no meio de vós."},
{v:15,t:"O homem que se unir a um animal será morto, e matareis também o animal."},
{v:16,t:"Se uma mulher se aproximar de qualquer animal para se unir a ele, matarás a mulher e o animal: serão mortos; o seu sangue está sobre eles."},
{v:17,t:"Se um homem tomar a sua irmã, filha do seu pai ou filha da sua mãe, e vir a nudez dela, e ela vir a nudez dele, é uma ignomínia: serão eliminados à vista dos filhos do seu povo; ele descobriu a nudez da sua irmã, carregará a sua iniquidade."},
{v:18,t:"Se um homem se deitar com uma mulher durante a sua menstruação e descobrir a sua nudez, ele pôs a descoberto a fonte dela, e ela descobriu a fonte do seu sangue: ambos serão eliminados do meio do seu povo."},
{v:19,t:"Não descobrirás a nudez da irmã da tua mãe nem da irmã do teu pai, porque isso é pôr a descoberto a própria carne: carregarão a sua iniquidade."},
{v:20,t:"O homem que se deitar com a sua tia descobriu a nudez do seu tio: carregarão o seu pecado; morrerão sem filhos."},
{v:21,t:"O homem que tomar a mulher do seu irmão comete uma impureza: descobriu a nudez do seu irmão; ficarão sem filhos."},
{v:22,t:"Guardareis todos os meus preceitos e todos os meus juízos, e os praticareis, para que não vos vomite a terra para a qual vos levo, para nela habitardes."},
{v:23,t:"Não andareis segundo os costumes da nação que expulso de diante de vós, porque fizeram todas essas coisas, e eu me enfadei deles."},
{v:24,t:"E vos disse: Vós possuireis a terra deles; eu a darei a vós, para que a possuais, terra que mana leite e mel. Eu sou o Senhor vosso Deus, que vos separei dos povos."},
{v:25,t:"Fareis, pois, distinção entre o animal puro e o impuro, entre a ave impura e a pura, e não vos torneis abomináveis por causa de animal, de ave ou de qualquer coisa que rasteja sobre o solo, que eu separei para vós como impuros."},
{v:26,t:"Sereis santos para mim, porque eu, o Senhor, sou santo, e vos separei dos povos para serdes meus."},
{v:27,t:"O homem ou a mulher em quem houver espírito de necromante ou de adivinho serão mortos: serão apedrejados; o seu sangue está sobre eles."}
];

window.TEXTOS_SEED["levitico"][21] = [
{v:1,t:"O Senhor disse a Moisés: Fala aos sacerdotes, filhos de Aarão, e dize a eles: Nenhum sacerdote se contamine por causa de um morto do seu povo,"},
{v:2,t:"a não ser pelos parentes mais próximos: pela mãe, pelo pai, pelo filho, pela filha, pelo irmão"},
{v:3,t:"e pela irmã virgem, que lhe é próxima por não ter pertencido a um homem: por ela poderá contaminar-se."},
{v:4,t:"Não se contaminará, como esposo, entre os do seu povo, profanando-se.",n:"O hebraico do versículo é obscuro; entende-se em geral que o sacerdote não deve contaminar-se pelos parentes por afinidade, isto é, os do lado da esposa."},
{v:5,t:"Os sacerdotes não raparão a cabeça, não cortarão as pontas da barba nem farão incisões na sua carne."},
{v:6,t:"Serão santos para o seu Deus e não profanarão o nome do seu Deus, porque são eles que apresentam as ofertas queimadas ao Senhor, o pão do seu Deus: por isso serão santos."},
{v:7,t:"Não tomarão por mulher uma prostituta ou uma mulher desonrada, nem tomarão uma mulher repudiada pelo marido, porque o sacerdote é santo para o seu Deus."},
{v:8,t:"Tu o terás por santo, porque ele apresenta o pão do teu Deus: será santo para ti, porque eu, o Senhor, que vos santifico, sou santo."},
{v:9,t:"Se a filha de um sacerdote se profanar, prostituindo-se, profana o seu pai: será queimada no fogo."},
{v:10,t:"O sacerdote que é o maior entre os seus irmãos, sobre cuja cabeça foi derramado o óleo da unção e que foi investido para vestir as vestes sagradas, não deixará os cabelos em desalinho nem rasgará as suas vestes."},
{v:11,t:"Não se aproximará de nenhum morto; nem pelo seu pai nem pela sua mãe se contaminará."},
{v:12,t:"Não sairá do santuário, para não profanar o santuário do seu Deus, porque está sobre ele a consagração do óleo da unção do seu Deus. Eu sou o Senhor."},
{v:13,t:"Ele tomará por mulher uma virgem."},
{v:14,t:"Não tomará viúva, nem repudiada, nem desonrada, nem prostituta, mas tomará por mulher uma virgem do seu povo,"},
{v:15,t:"para não profanar a sua descendência no meio do seu povo. Porque eu sou o Senhor, que o santifico."},
{v:16,t:"O Senhor falou a Moisés, dizendo:"},
{v:17,t:"Fala a Aarão: Nenhum homem da tua descendência, pelas suas gerações, que tiver algum defeito, se aproximará para apresentar o pão do seu Deus."},
{v:18,t:"Porque nenhum homem que tiver defeito se aproximará: nem o cego, nem o coxo, nem o de rosto mutilado, nem o desproporcionado,"},
{v:19,t:"nem o homem que tiver o pé quebrado ou a mão quebrada,"},
{v:20,t:"nem o corcunda, nem o anão, nem o que tiver mancha no olho, sarna, impetigem ou os testículos esmagados."},
{v:21,t:"Nenhum homem da descendência do sacerdote Aarão que tiver defeito se aproximará para apresentar as ofertas queimadas ao Senhor: tem defeito, não se aproximará para apresentar o pão do seu Deus."},
{v:22,t:"Poderá comer o pão do seu Deus, tanto das coisas santíssimas como das coisas santas;"},
{v:23,t:"mas não entrará até o véu nem se aproximará do altar, porque tem defeito, para não profanar os meus santuários. Porque eu sou o Senhor, que os santifico."},
{v:24,t:"Assim falou Moisés a Aarão e a seus filhos, e a todos os filhos de Israel."}
];

window.TEXTOS_SEED["levitico"][22] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala a Aarão e a seus filhos, para que tratem com respeito as coisas santas dos filhos de Israel, que eles me consagram, e não profanem o meu santo nome. Eu sou o Senhor."},
{v:3,t:"Dize a eles: Pelas vossas gerações, todo homem da vossa descendência que, estando impuro, se aproximar das coisas santas que os filhos de Israel consagram ao Senhor, será eliminado da minha presença. Eu sou o Senhor."},
{v:4,t:"Nenhum homem da descendência de Aarão que for leproso ou tiver um fluxo comerá das coisas santas, até que fique puro. Quem tocar qualquer coisa contaminada por um morto, ou o homem de quem sair emissão de sêmen,"},
{v:5,t:"ou quem tocar qualquer réptil pelo qual se torne impuro, ou um homem pelo qual se torne impuro, qualquer que seja a sua impureza,"},
{v:6,t:"a pessoa que tocar tais coisas ficará impura até a tarde e não comerá das coisas santas, sem antes banhar o corpo na água."},
{v:7,t:"Posto o sol, ficará pura, e depois comerá das coisas santas, porque são o seu alimento."},
{v:8,t:"Não comerá animal morto nem dilacerado, para não se contaminar com ele. Eu sou o Senhor."},
{v:9,t:"Guardarão a minha observância, para não carregarem pecado por causa disso e não morrerem por o terem profanado. Eu sou o Senhor, que os santifico."},
{v:10,t:"Nenhum estranho comerá das coisas santas; nem o hóspede do sacerdote nem o diarista comerão das coisas santas."},
{v:11,t:"Mas o escravo que o sacerdote tiver comprado com o seu dinheiro, esse poderá comer delas, assim como os nascidos na sua casa: esses comerão do seu pão."},
{v:12,t:"A filha de um sacerdote que se casar com um estranho não comerá das coisas santas oferecidas;"},
{v:13,t:"mas, se a filha do sacerdote ficar viúva ou for repudiada, sem ter filhos, e voltar à casa do seu pai, como na sua juventude, comerá do pão do seu pai. Nenhum estranho comerá dele."},
{v:14,t:"Quem comer por inadvertência de uma coisa santa acrescentará um quinto e dará ao sacerdote a coisa santa."},
{v:15,t:"Os sacerdotes não profanarão as coisas santas dos filhos de Israel, que eles apresentam ao Senhor como oferta elevada,"},
{v:16,t:"para não os fazerem carregar a iniquidade de uma falta, comendo as suas coisas santas. Porque eu sou o Senhor, que as santifico."},
{v:17,t:"O Senhor falou a Moisés, dizendo:"},
{v:18,t:"Fala a Aarão, a seus filhos e a todos os filhos de Israel, e dize a eles: Qualquer homem da casa de Israel, ou dos estrangeiros em Israel, que apresentar a sua oferta, seja em cumprimento de voto, seja como oferta espontânea, e a apresentar ao Senhor em holocausto,"},
{v:19,t:"para que seja aceita em vosso favor, será um macho sem defeito, dos bois, das ovelhas ou das cabras."},
{v:20,t:"Não apresentareis nada que tenha defeito, porque não seria aceito em vosso favor."},
{v:21,t:"Quando alguém apresentar ao Senhor um sacrifício de comunhão, em cumprimento de voto ou como oferta espontânea, do gado graúdo ou do gado miúdo, o animal, para ser aceito, será perfeito: não haverá nele defeito algum."},
{v:22,t:"Animal cego, ou aleijado, ou mutilado, ou com úlceras, ou com sarna, ou com impetigem, não o apresentareis ao Senhor, nem dele poreis oferta queimada sobre o altar do Senhor."},
{v:23,t:"O boi ou a ovelha com um membro desproporcionado ou atrofiado, poderás oferecer como oferta espontânea, mas em cumprimento de voto não seria aceito."},
{v:24,t:"Animal com os testículos machucados, ou esmagados, ou arrancados, ou cortados, não o apresentareis ao Senhor: não fareis isso na vossa terra."},
{v:25,t:"Nem da mão do estrangeiro apresentareis animais desses como pão do vosso Deus, porque neles há corrupção e defeito: não seriam aceitos em vosso favor."},
{v:26,t:"O Senhor falou a Moisés, dizendo:"},
{v:27,t:"Quando nascer um bezerro, um cordeiro ou um cabrito, ficará sete dias com a sua mãe; do oitavo dia em diante será aceito como oferta queimada ao Senhor."},
{v:28,t:"Não imolareis no mesmo dia a vaca ou a ovelha junto com a sua cria."},
{v:29,t:"Quando imolardes um sacrifício de ação de graças ao Senhor, vós o imolareis de modo que seja aceito em vosso favor:"},
{v:30,t:"será comido no mesmo dia; não deixareis nada dele até de manhã. Eu sou o Senhor."},
{v:31,t:"Guardareis os meus mandamentos e os praticareis. Eu sou o Senhor."},
{v:32,t:"Não profanareis o meu santo nome, para que eu seja santificado no meio dos filhos de Israel. Eu sou o Senhor, que vos santifico,"},
{v:33,t:"que vos fiz sair da terra do Egito, para ser o vosso Deus. Eu sou o Senhor."}
];

window.TEXTOS_SEED["levitico"][23] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala aos filhos de Israel e dize a eles: As festas do Senhor, que convocareis como assembleias santas, estas são as minhas festas."},
{v:3,t:"Durante seis dias se fará o trabalho; o sétimo dia é sábado de repouso completo, assembleia santa: não fareis trabalho algum; é sábado do Senhor em todas as vossas moradas."},
{v:4,t:"Estas são as festas do Senhor, as assembleias santas que convocareis nos seus tempos determinados."},
{v:5,t:"No primeiro mês, no dia catorze do mês, ao entardecer, é a Páscoa do Senhor.",n:"Ao entardecer verte a expressão hebraica entre as duas tardes, isto é, entre o declínio do sol e o anoitecer."},
{v:6,t:"No dia quinze desse mês é a festa dos Ázimos do Senhor: durante sete dias comereis pães ázimos."},
{v:7,t:"No primeiro dia tereis assembleia santa: não fareis nenhum trabalho servil."},
{v:8,t:"Durante sete dias apresentareis ofertas queimadas ao Senhor. No sétimo dia haverá assembleia santa: não fareis nenhum trabalho servil."},
{v:9,t:"O Senhor falou a Moisés, dizendo:"},
{v:10,t:"Fala aos filhos de Israel e dize a eles: Quando tiverdes entrado na terra que vos dou e fizerdes a sua colheita, trareis ao sacerdote o primeiro feixe da vossa colheita."},
{v:11,t:"Ele moverá o feixe com um gesto para a frente e para trás diante do Senhor, para que sejais aceitos: o sacerdote o moverá no dia seguinte ao sábado.",n:"No dia seguinte ao sábado: expressão muito discutida já entre os antigos; a tradição que a Igreja recebeu entende o dia seguinte ao primeiro dia festivo da Páscoa. É significativo que Cristo, primícias dos que dormem (1 Cor 15, 20), ressuscitou no dia seguinte ao sábado."},
{v:12,t:"No dia em que moverdes o feixe, oferecereis um cordeiro de um ano, sem defeito, em holocausto ao Senhor,"},
{v:13,t:"com a sua oblação de dois décimos de efá de flor de farinha amassada com azeite, como oferta queimada de aroma agradável ao Senhor, e com a sua libação de um quarto de him de vinho."},
{v:14,t:"Não comereis pão, nem grão tostado, nem trigo novo, até esse mesmo dia, até que tragais a oferta do vosso Deus: é preceito perpétuo pelas vossas gerações, em todas as vossas moradas."},
{v:15,t:"Contareis, a partir do dia seguinte ao sábado, do dia em que trouxerdes o feixe da oferenda movida, sete semanas completas."},
{v:16,t:"Contareis cinquenta dias, até o dia seguinte ao sétimo sábado, e então apresentareis ao Senhor uma oblação nova.",n:"Destes cinquenta dias vem o nome grego Pentecostes, a festa das Semanas, na qual o Espírito Santo desceu sobre a Igreja (At 2)."},
{v:17,t:"Trareis das vossas moradas dois pães para a oferenda movida; serão de dois décimos de efá de flor de farinha, cozidos com fermento: são as primícias para o Senhor."},
{v:18,t:"Com os pães apresentareis sete cordeiros de um ano, sem defeito, um novilho e dois carneiros: serão holocausto ao Senhor, com as suas oblações e libações, oferta queimada de aroma agradável ao Senhor."},
{v:19,t:"Oferecereis também um bode como sacrifício pelo pecado e dois cordeiros de um ano como sacrifício de comunhão."},
{v:20,t:"O sacerdote os moverá, com o pão das primícias, com um gesto para a frente e para trás, como oferenda movida diante do Senhor, com os dois cordeiros: serão coisa santa para o Senhor, e pertencerão ao sacerdote."},
{v:21,t:"Nesse mesmo dia convocareis assembleia santa: não fareis nenhum trabalho servil; é preceito perpétuo pelas vossas gerações, em todas as vossas moradas."},
{v:22,t:"Quando fizerdes a colheita da vossa terra, não segarás o teu campo até a beirada nem recolherás as espigas caídas da tua colheita: tu as deixarás para o pobre e para o estrangeiro. Eu sou o Senhor vosso Deus."},
{v:23,t:"O Senhor falou a Moisés, dizendo:"},
{v:24,t:"Fala aos filhos de Israel: No sétimo mês, no primeiro dia do mês, tereis um repouso solene, um memorial ao som das trombetas, uma assembleia santa."},
{v:25,t:"Não fareis nenhum trabalho servil e apresentareis uma oferta queimada ao Senhor."},
{v:26,t:"O Senhor falou a Moisés, dizendo:"},
{v:27,t:"No décimo dia desse sétimo mês é o dia da Expiação: tereis assembleia santa, afligireis as vossas almas e apresentareis uma oferta queimada ao Senhor."},
{v:28,t:"Nesse dia não fareis trabalho algum, porque é dia de expiação, para se fazer expiação por vós diante do Senhor vosso Deus."},
{v:29,t:"Toda pessoa que não se afligir nesse dia será eliminada do seu povo;"},
{v:30,t:"e toda pessoa que fizer qualquer trabalho nesse dia, eu a farei perecer do meio do seu povo."},
{v:31,t:"Não fareis trabalho algum: é preceito perpétuo pelas vossas gerações, em todas as vossas moradas."},
{v:32,t:"Será para vós sábado de repouso completo, e afligireis as vossas almas; do entardecer do nono dia do mês até o entardecer seguinte, guardareis o vosso sábado."},
{v:33,t:"O Senhor falou a Moisés, dizendo:"},
{v:34,t:"Fala aos filhos de Israel: No dia quinze desse sétimo mês é a festa das Tendas, durante sete dias, em honra do Senhor."},
{v:35,t:"No primeiro dia haverá assembleia santa: não fareis nenhum trabalho servil."},
{v:36,t:"Durante sete dias apresentareis ofertas queimadas ao Senhor. No oitavo dia tereis assembleia santa e apresentareis uma oferta queimada ao Senhor: é uma reunião solene; não fareis nenhum trabalho servil."},
{v:37,t:"Estas são as festas do Senhor, que convocareis como assembleias santas, para apresentar ofertas queimadas ao Senhor: holocaustos e oblações, sacrifícios e libações, cada coisa no seu dia,"},
{v:38,t:"além dos sábados do Senhor, além dos vossos dons, além de todos os vossos votos e além de todas as vossas ofertas espontâneas, que apresentardes ao Senhor."},
{v:39,t:"Mas, no dia quinze do sétimo mês, quando tiverdes recolhido os frutos da terra, celebrareis a festa do Senhor durante sete dias; no primeiro dia haverá repouso, e no oitavo dia haverá repouso."},
{v:40,t:"No primeiro dia tomareis frutos das mais belas árvores, ramos de palmeiras, ramos de árvores frondosas e salgueiros da torrente, e vos alegrareis diante do Senhor vosso Deus durante sete dias."},
{v:41,t:"Celebrareis esta festa em honra do Senhor sete dias por ano: é preceito perpétuo pelas vossas gerações; vós a celebrareis no sétimo mês."},
{v:42,t:"Habitareis em tendas durante sete dias; todos os naturais de Israel habitarão em tendas,"},
{v:43,t:"para que as vossas gerações saibam que eu fiz habitar em tendas os filhos de Israel, quando os fiz sair da terra do Egito. Eu sou o Senhor vosso Deus."},
{v:44,t:"E Moisés declarou aos filhos de Israel as festas do Senhor."}
];

window.TEXTOS_SEED["levitico"][24] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Ordena aos filhos de Israel que te tragam azeite puro de olivas batidas, para o candelabro, a fim de manter as lâmpadas acesas continuamente."},
{v:3,t:"Fora do véu do testemunho, na tenda do encontro, Aarão o preparará, para que arda do entardecer até de manhã, diante do Senhor, continuamente: é preceito perpétuo pelas vossas gerações."},
{v:4,t:"Sobre o candelabro puro ele disporá as lâmpadas, diante do Senhor, continuamente."},
{v:5,t:"Tomarás flor de farinha e dela cozerás doze pães: cada pão será de dois décimos de efá."},
{v:6,t:"Tu os disporás em duas fileiras, seis em cada fileira, sobre a mesa pura, diante do Senhor."},
{v:7,t:"Sobre cada fileira porás incenso puro, que será para o pão um memorial, oferta queimada ao Senhor."},
{v:8,t:"A cada sábado ele os disporá continuamente diante do Senhor, da parte dos filhos de Israel: é aliança perpétua."},
{v:9,t:"Pertencerão a Aarão e a seus filhos, que os comerão em lugar santo, porque são para ele coisa santíssima dentre as ofertas queimadas ao Senhor: é preceito perpétuo.",n:"São estes os pães da proposição que Davi comeu (1 Sm 21) e que o Senhor Jesus recorda em Mt 12, 4."},
{v:10,t:"O filho de uma mulher israelita, filho de um homem egípcio, saiu no meio dos filhos de Israel; e no acampamento brigaram o filho da israelita e um homem israelita."},
{v:11,t:"O filho da mulher israelita blasfemou o Nome e o amaldiçoou; e o levaram a Moisés. O nome da sua mãe era Salomite, filha de Dibri, da tribo de Dã.",n:"O Nome, em absoluto, designa o nome próprio de Deus, o Tetragrama, que o texto evita pronunciar até ao referir a blasfêmia."},
{v:12,t:"Puseram-no sob guarda, até que houvesse decisão pela palavra do Senhor."},
{v:13,t:"O Senhor falou a Moisés, dizendo:"},
{v:14,t:"Leva o blasfemo para fora do acampamento; todos os que o ouviram porão as mãos sobre a cabeça dele, e toda a comunidade o apedrejará."},
{v:15,t:"E dirás aos filhos de Israel: Todo homem que amaldiçoar o seu Deus carregará o seu pecado;"},
{v:16,t:"quem blasfemar o nome do Senhor será morto: toda a comunidade o apedrejará. Tanto o estrangeiro como o natural da terra, se blasfemar o Nome, será morto."},
{v:17,t:"Quem ferir de morte qualquer homem será morto."},
{v:18,t:"Quem ferir de morte um animal o restituirá: vida por vida."},
{v:19,t:"Se alguém causar uma lesão ao seu próximo, como fez, assim se fará a ele:"},
{v:20,t:"fratura por fratura, olho por olho, dente por dente; a lesão que causou a outrem, essa mesma sofrerá.",n:"A lei de talião, que limita a vingança à medida exata do dano, e que o Senhor Jesus levará à plenitude no sermão da montanha (Mt 5, 38)."},
{v:21,t:"Quem matar um animal o restituirá; quem matar um homem será morto."},
{v:22,t:"Tereis um único direito, tanto para o estrangeiro como para o natural da terra. Porque eu sou o Senhor vosso Deus."},
{v:23,t:"Moisés falou aos filhos de Israel, e eles levaram o blasfemo para fora do acampamento e o apedrejaram. Os filhos de Israel fizeram como o Senhor ordenara a Moisés."}
];

window.TEXTOS_SEED["levitico"][25] = [
{v:1,t:"O Senhor falou a Moisés no monte Sinai, dizendo:"},
{v:2,t:"Fala aos filhos de Israel e dize a eles: Quando tiverdes entrado na terra que vos dou, a terra guardará um sábado em honra do Senhor."},
{v:3,t:"Durante seis anos semearás o teu campo, durante seis anos podarás a tua vinha e recolherás os seus frutos;"},
{v:4,t:"mas no sétimo ano haverá sábado de repouso completo para a terra, um sábado em honra do Senhor: não semearás o teu campo nem podarás a tua vinha."},
{v:5,t:"Não ceifarás o que nascer por si da tua colheita nem vindimarás as uvas da tua vinha não podada: será ano de repouso completo para a terra."},
{v:6,t:"O sábado da terra vos servirá de alimento: a ti, ao teu escravo, à tua escrava, ao teu diarista e ao hóspede que mora contigo;"},
{v:7,t:"também ao teu gado e aos animais que estão na tua terra, todo o seu produto servirá de alimento."},
{v:8,t:"Contarás sete semanas de anos, sete vezes sete anos, de modo que o tempo das sete semanas de anos dê quarenta e nove anos."},
{v:9,t:"No sétimo mês, no décimo dia do mês, farás soar a trombeta: no dia da Expiação fareis soar a trombeta por toda a vossa terra."},
{v:10,t:"Santificareis o ano quinquagésimo e proclamareis na terra a libertação para todos os seus habitantes: será para vós um jubileu; cada um de vós voltará à sua propriedade, cada um de vós voltará à sua família.",n:"Jubileu vem do hebraico yobel, o chifre de carneiro cujo toque abria o ano santo. Deste versículo a Igreja tomou o nome e o sentido dos seus anos jubilares."},
{v:11,t:"O quinquagésimo ano será para vós um jubileu: não semeareis, não ceifareis o que nascer por si nem vindimareis a vinha não podada;"},
{v:12,t:"porque é o jubileu: será santo para vós. Comereis o que os campos derem por si."},
{v:13,t:"Nesse ano do jubileu, cada um de vós voltará à sua propriedade."},
{v:14,t:"Quando venderes algo ao teu próximo ou comprares algo da mão do teu próximo, ninguém prejudique o seu irmão."},
{v:15,t:"Comprarás do teu próximo segundo o número de anos decorridos desde o jubileu, e ele venderá a ti segundo o número de anos de colheita."},
{v:16,t:"Quanto mais anos restarem, mais elevado será o preço; quanto menos anos, menor será o preço: porque é o número de colheitas que ele vende a ti."},
{v:17,t:"Ninguém prejudique o seu próximo, mas temerás o teu Deus. Porque eu sou o Senhor vosso Deus."},
{v:18,t:"Praticareis os meus preceitos, guardareis os meus juízos e os praticareis, e habitareis em segurança na terra."},
{v:19,t:"A terra dará o seu fruto, comereis até vos saciar e habitareis nela em segurança."},
{v:20,t:"Se disserdes: Que comeremos no sétimo ano, se não semearmos nem recolhermos a nossa colheita?,"},
{v:21,t:"eu ordenarei a minha bênção sobre vós no sexto ano, e ele produzirá colheita para três anos."},
{v:22,t:"Semeareis no oitavo ano e ainda comereis da colheita velha; até o nono ano, até que venha a sua colheita, comereis da velha."},
{v:23,t:"A terra não será vendida para sempre, porque a terra é minha, e vós sois estrangeiros e hóspedes junto a mim."},
{v:24,t:"Por isso, em toda a terra da vossa possessão, concedereis o direito de resgate da terra."},
{v:25,t:"Se o teu irmão empobrecer e vender parte da sua propriedade, virá como resgatador o seu parente mais próximo e resgatará o que o seu irmão vendeu.",n:"Resgatador traduz goel, o parente a quem cabia resgatar a terra e a pessoa; o termo, aplicado a Deus pelos profetas, prepara o título de Redentor."},
{v:26,t:"Se alguém não tiver resgatador, mas ele mesmo conseguir encontrar o suficiente para o resgate,"},
{v:27,t:"contará os anos decorridos desde a venda, restituirá a diferença ao homem a quem vendeu, e voltará à sua propriedade."},
{v:28,t:"Mas, se não encontrar o suficiente para lhe restituir, o que vendeu ficará na mão do comprador até o ano do jubileu; no jubileu, ficará livre, e ele voltará à sua propriedade."},
{v:29,t:"Se alguém vender uma casa de morada em cidade murada, terá direito de resgate até completar-se o ano da venda: o seu direito de resgate durará um ano."},
{v:30,t:"Se não for resgatada antes de decorrido um ano inteiro, a casa situada em cidade murada ficará para sempre com o comprador, pelas suas gerações: não ficará livre no jubileu."},
{v:31,t:"Mas as casas das aldeias sem muros ao redor serão contadas como os campos da terra: haverá para elas resgate, e no jubileu ficarão livres."},
{v:32,t:"Quanto às cidades dos levitas, os levitas terão direito perpétuo de resgate das casas das cidades da sua possessão."},
{v:33,t:"Se alguém comprar dos levitas uma casa, a casa vendida na cidade da sua possessão ficará livre no jubileu, porque as casas das cidades dos levitas são a sua propriedade no meio dos filhos de Israel."},
{v:34,t:"Os campos dos arredores das suas cidades não serão vendidos, porque são a sua propriedade perpétua."},
{v:35,t:"Se o teu irmão empobrecer e a sua mão vacilar junto de ti, tu o susterás, como estrangeiro e hóspede, para que viva contigo."},
{v:36,t:"Não tomarás dele juros nem lucro, mas temerás o teu Deus, para que o teu irmão viva contigo."},
{v:37,t:"Não lhe darás o teu dinheiro a juros nem lhe darás o teu alimento com lucro."},
{v:38,t:"Eu sou o Senhor vosso Deus, que vos fiz sair da terra do Egito, para vos dar a terra de Canaã e ser o vosso Deus."},
{v:39,t:"Se o teu irmão empobrecer junto de ti e se vender a ti, não o farás servir como escravo:"},
{v:40,t:"estará contigo como diarista, como hóspede; servirá junto de ti até o ano do jubileu."},
{v:41,t:"Então sairá da tua casa, ele e os seus filhos com ele, e voltará à sua família e à propriedade dos seus pais."},
{v:42,t:"Porque são meus servos, que fiz sair da terra do Egito: não serão vendidos como se vendem os escravos."},
{v:43,t:"Não dominarás sobre ele com dureza, mas temerás o teu Deus."},
{v:44,t:"O escravo e a escrava que tiveres virão das nações que estão ao vosso redor: delas comprareis escravo e escrava."},
{v:45,t:"Também dos filhos dos hóspedes que moram convosco podereis comprar, e das suas famílias que estão convosco, dos que nasceram na vossa terra: serão vossa propriedade."},
{v:46,t:"Vós os deixareis por herança aos vossos filhos depois de vós, como propriedade: deles vos servireis para sempre. Mas sobre os vossos irmãos, os filhos de Israel, ninguém dominará sobre o seu irmão com dureza."},
{v:47,t:"Se um estrangeiro ou hóspede junto de ti enriquecer, e o teu irmão junto dele empobrecer e se vender ao estrangeiro que é hóspede junto de ti, ou a alguém da família de um estrangeiro,"},
{v:48,t:"depois de vendido, haverá para ele direito de resgate: um dos seus irmãos o resgatará;"},
{v:49,t:"ou o seu tio, ou o filho do seu tio o resgatará, ou algum parente próximo da sua família o resgatará; ou, se conseguir, ele se resgatará a si mesmo."},
{v:50,t:"Fará as contas com o seu comprador, desde o ano em que se vendeu até o ano do jubileu, e o preço da sua venda será segundo o número dos anos, contando-se os seus dias como os de um diarista."},
{v:51,t:"Se ainda faltarem muitos anos, restituirá como resgate, do dinheiro da compra, a parte proporcional a eles;"},
{v:52,t:"se faltarem poucos anos até o ano do jubileu, fará as contas com ele e restituirá o resgate segundo os anos que faltam,"},
{v:53,t:"como quem é diarista ano após ano. Não se dominará sobre ele com dureza, à tua vista."},
{v:54,t:"Se não for resgatado por nenhum desses modos, sairá livre no ano do jubileu, ele e os seus filhos com ele."},
{v:55,t:"Porque os filhos de Israel são meus servos; são meus servos, que fiz sair da terra do Egito. Eu sou o Senhor vosso Deus."}
];

window.TEXTOS_SEED["levitico"][26] = [
{v:1,t:"Não fareis para vós ídolos, não levantareis imagem esculpida nem estela, nem poreis na vossa terra pedra com figuras, para vos prostrardes diante dela. Porque eu sou o Senhor vosso Deus."},
{v:2,t:"Guardareis os meus sábados e reverenciareis o meu santuário. Eu sou o Senhor."},
{v:3,t:"Se andardes nos meus preceitos, guardardes os meus mandamentos e os praticardes,"},
{v:4,t:"eu vos darei as chuvas nos seus tempos, a terra dará o seu produto, e a árvore do campo dará o seu fruto."},
{v:5,t:"A debulha alcançará entre vós a vindima, e a vindima alcançará a semeadura; comereis o vosso pão até vos saciar e habitareis em segurança na vossa terra."},
{v:6,t:"Estabelecerei a paz na terra: vos deitareis, e ninguém vos espantará; farei desaparecer da terra as feras, e a espada não passará pela vossa terra."},
{v:7,t:"Perseguireis os vossos inimigos, e eles cairão diante de vós à espada."},
{v:8,t:"Cinco de vós perseguirão cem, e cem de vós perseguirão dez mil: os vossos inimigos cairão diante de vós à espada."},
{v:9,t:"Eu me voltarei para vós, vos farei fecundos e vos multiplicarei, e confirmarei a minha aliança convosco."},
{v:10,t:"Comereis da colheita velha, guardada por muito tempo, e tirareis fora a velha para dar lugar à nova."},
{v:11,t:"Porei a minha morada no meio de vós, e a minha alma não vos abominará."},
{v:12,t:"Andarei no meio de vós, serei o vosso Deus, e vós sereis o meu povo.",n:"Promessa central da aliança, que os profetas retomam e o Apocalipse (21, 3) vê consumada na Jerusalém celeste."},
{v:13,t:"Eu sou o Senhor vosso Deus, que vos fiz sair da terra do Egito, para que não fôsseis seus escravos; quebrei as cangas do vosso jugo e vos fiz andar de cabeça erguida."},
{v:14,t:"Mas, se não me ouvirdes nem praticardes todos estes mandamentos,"},
{v:15,t:"se desprezardes os meus preceitos e a vossa alma se enfadar dos meus juízos, deixando de praticar todos os meus mandamentos e rompendo a minha aliança,"},
{v:16,t:"eu também farei isto convosco: mandarei sobre vós o terror, a tísica e a febre, que consomem os olhos e definham a alma; semeareis em vão a vossa semente, porque os vossos inimigos a comerão."},
{v:17,t:"Voltarei a minha face contra vós, e sereis derrotados diante dos vossos inimigos; os que vos odeiam dominarão sobre vós, e fugireis sem que ninguém vos persiga."},
{v:18,t:"Se nem assim me ouvirdes, continuarei a vos corrigir sete vezes mais, por causa dos vossos pecados."},
{v:19,t:"Quebrarei a soberba da vossa força: farei que o vosso céu seja como ferro, e a vossa terra como bronze."},
{v:20,t:"A vossa força se gastará em vão: a vossa terra não dará o seu produto, e a árvore da terra não dará o seu fruto."},
{v:21,t:"Se andardes contra mim e não quiserdes ouvir-me, eu vos ferirei sete vezes mais, segundo os vossos pecados."},
{v:22,t:"Mandarei contra vós as feras do campo, que vos privarão dos filhos, exterminarão o vosso gado e vos reduzirão a poucos, e os vossos caminhos ficarão desertos."},
{v:23,t:"Se nem com isso vos deixardes corrigir por mim, mas andardes contra mim,"},
{v:24,t:"eu também andarei contra vós e vos ferirei, eu mesmo, sete vezes, por causa dos vossos pecados."},
{v:25,t:"Farei vir sobre vós a espada vingadora da aliança; vos refugiareis nas vossas cidades, mas mandarei a peste para o meio de vós, e sereis entregues na mão do inimigo."},
{v:26,t:"Quando eu vos quebrar o sustento do pão, dez mulheres cozerão o vosso pão num só forno e vos devolverão o pão por peso: comereis e não vos saciareis."},
{v:27,t:"Se nem com isso me ouvirdes, mas andardes contra mim,"},
{v:28,t:"eu andarei contra vós com furor e vos corrigirei, eu mesmo, sete vezes, por causa dos vossos pecados."},
{v:29,t:"Comereis a carne dos vossos filhos, e a carne das vossas filhas comereis."},
{v:30,t:"Destruirei os vossos lugares altos, derrubarei os vossos altares de incenso, amontoarei os vossos cadáveres sobre os cadáveres dos vossos ídolos, e a minha alma vos abominará."},
{v:31,t:"Reduzirei as vossas cidades a ruínas, devastarei os vossos santuários e não mais aspirarei o vosso aroma agradável."},
{v:32,t:"Eu mesmo devastarei a terra, e os vossos inimigos que vierem habitar nela ficarão pasmados diante dela."},
{v:33,t:"E a vós, eu vos espalharei entre as nações e desembainharei a espada atrás de vós; a vossa terra ficará devastada, e as vossas cidades, em ruínas."},
{v:34,t:"Então a terra desfrutará os seus sábados, todos os dias da sua desolação, enquanto estiverdes na terra dos vossos inimigos: então a terra repousará e desfrutará os seus sábados."},
{v:35,t:"Todos os dias da sua desolação repousará, pelo que não repousou nos vossos sábados, quando habitáveis nela."},
{v:36,t:"Aos que restarem de vós, porei tal pavor nos corações, nas terras dos seus inimigos, que o ruído de uma folha levada pelo vento os porá em fuga; fugirão como quem foge da espada e cairão sem que ninguém os persiga."},
{v:37,t:"Tropeçarão uns nos outros, como diante da espada, sem que ninguém os persiga; não podereis resistir diante dos vossos inimigos."},
{v:38,t:"Perecereis entre as nações, e a terra dos vossos inimigos vos devorará."},
{v:39,t:"Os que restarem de vós definharão por causa da sua iniquidade, nas terras dos vossos inimigos; e também por causa das iniquidades dos seus pais definharão com eles."},
{v:40,t:"Então confessarão a sua iniquidade e a iniquidade dos seus pais, a infidelidade que cometeram contra mim, e também que andaram contra mim,"},
{v:41,t:"pelo que eu também andei contra eles e os levei à terra dos seus inimigos. Se então se humilhar o seu coração incircunciso e eles pagarem pela sua iniquidade,"},
{v:42,t:"eu me lembrarei da minha aliança com Jacó, da minha aliança com Isaac e também da minha aliança com Abraão me lembrarei, e da terra me lembrarei."},
{v:43,t:"A terra, abandonada por eles, desfrutará os seus sábados, enquanto estiver desolada, sem eles; e eles pagarão pela sua iniquidade, por terem desprezado os meus juízos e por a sua alma se ter enfadado dos meus preceitos."},
{v:44,t:"Mas, apesar de tudo isso, quando estiverem na terra dos seus inimigos, não os desprezarei nem me enfadarei deles a ponto de os exterminar, rompendo a minha aliança com eles. Porque eu sou o Senhor, seu Deus."},
{v:45,t:"Por causa deles, eu me lembrarei da aliança com os seus antepassados, que fiz sair da terra do Egito, à vista das nações, para ser o seu Deus. Eu sou o Senhor."},
{v:46,t:"Estes são os preceitos, os juízos e as leis que o Senhor estabeleceu entre si e os filhos de Israel, no monte Sinai, por meio de Moisés."}
];

window.TEXTOS_SEED["levitico"][27] = [
{v:1,t:"O Senhor falou a Moisés, dizendo:"},
{v:2,t:"Fala aos filhos de Israel e dize a eles: Quando alguém fizer ao Senhor um voto que envolva a avaliação de pessoas,"},
{v:3,t:"se for um homem de vinte a sessenta anos, a avaliação será de cinquenta siclos de prata, segundo o siclo do santuário;"},
{v:4,t:"se for mulher, a avaliação será de trinta siclos."},
{v:5,t:"Dos cinco aos vinte anos, a avaliação será: para o homem, vinte siclos; para a mulher, dez siclos."},
{v:6,t:"De um mês aos cinco anos, a avaliação será: para o menino, cinco siclos de prata; para a menina, três siclos de prata."},
{v:7,t:"De sessenta anos para cima, se for homem, a avaliação será de quinze siclos; se for mulher, de dez siclos."},
{v:8,t:"Se for pobre demais para pagar a avaliação, será apresentado ao sacerdote, e o sacerdote fará a avaliação: o sacerdote fará a avaliação conforme os recursos de quem fez o voto."},
{v:9,t:"Se for um animal dos que se apresentam como oferta ao Senhor, tudo o que dele se der ao Senhor será santo."},
{v:10,t:"Não será trocado nem substituído: nem um bom por um mau, nem um mau por um bom; se de algum modo se substituir um animal por outro, tanto ele como o seu substituto serão santos."},
{v:11,t:"Se for um animal impuro, dos que não se apresentam como oferta ao Senhor, o animal será apresentado ao sacerdote,"},
{v:12,t:"e o sacerdote fará a avaliação, conforme seja bom ou mau: valerá conforme a avaliação do sacerdote."},
{v:13,t:"Se alguém o quiser resgatar, acrescentará um quinto à avaliação."},
{v:14,t:"Quando alguém consagrar a sua casa como coisa santa ao Senhor, o sacerdote fará a avaliação, conforme seja boa ou má: valerá conforme a avaliação do sacerdote."},
{v:15,t:"Se aquele que consagrou a casa a quiser resgatar, acrescentará um quinto ao dinheiro da avaliação, e ela será sua."},
{v:16,t:"Se alguém consagrar ao Senhor parte do campo da sua propriedade, a avaliação será conforme a semeadura: um hômer de semente de cevada valerá cinquenta siclos de prata.",n:"O hômer era medida de secos em torno de duzentos e vinte litros; a terra é avaliada pela semente que comporta."},
{v:17,t:"Se consagrar o campo a partir do ano do jubileu, valerá conforme a avaliação;"},
{v:18,t:"mas, se consagrar o campo depois do jubileu, o sacerdote calculará o preço segundo os anos que faltam para o ano do jubileu, e haverá redução na avaliação."},
{v:19,t:"Se aquele que consagrou o campo o quiser resgatar, acrescentará um quinto ao dinheiro da avaliação, e o campo será seu."},
{v:20,t:"Mas, se não resgatar o campo e o campo for vendido a outro, não poderá mais ser resgatado;"},
{v:21,t:"quando ficar livre no jubileu, o campo será santo para o Senhor, como campo votado ao interdito: será propriedade do sacerdote.",n:"Interdito traduz cherem: o que é subtraído para sempre ao uso profano e entregue irrevogavelmente a Deus."},
{v:22,t:"Se alguém consagrar ao Senhor um campo que comprou, que não é campo da sua propriedade,"},
{v:23,t:"o sacerdote calculará o montante da avaliação até o ano do jubileu, e nesse mesmo dia ele pagará a avaliação, como coisa santa para o Senhor."},
{v:24,t:"No ano do jubileu, o campo voltará àquele de quem foi comprado, àquele a quem pertence a propriedade da terra."},
{v:25,t:"Toda avaliação será feita segundo o siclo do santuário: o siclo tem vinte gueras."},
{v:26,t:"Contudo, ninguém consagrará o primogênito dos animais, que já pertence ao Senhor por ser primogênito: seja boi, seja ovelha, pertence ao Senhor."},
{v:27,t:"Se for de animal impuro, será resgatado conforme a avaliação, acrescentando-se um quinto; se não for resgatado, será vendido conforme a avaliação."},
{v:28,t:"Contudo, nada do que alguém votar ao Senhor sob interdito, de tudo o que possui, seja homem, seja animal, seja campo da sua propriedade, será vendido nem resgatado: tudo o que é votado ao interdito é coisa santíssima para o Senhor."},
{v:29,t:"Nenhuma pessoa votada ao interdito poderá ser resgatada: será morta."},
{v:30,t:"Todo dízimo da terra, dos grãos da terra ou dos frutos das árvores, pertence ao Senhor: é coisa santa para o Senhor."},
{v:31,t:"Se alguém quiser resgatar parte do seu dízimo, acrescentará um quinto."},
{v:32,t:"Todo dízimo do gado graúdo e do gado miúdo, de tudo o que passa sob o cajado do pastor, o décimo será coisa santa para o Senhor."},
{v:33,t:"Não se examinará se é bom ou mau, nem será substituído; se de algum modo for substituído, tanto ele como o seu substituto serão santos: não poderão ser resgatados."},
{v:34,t:"Estes são os mandamentos que o Senhor ordenou a Moisés, para os filhos de Israel, no monte Sinai."}
];

